var T5_INDEX = [["getting-started--open-take-5-for-the-first-time","Open Take 5 for the first time","Getting started","setting-up.html","open take 5 for the first time on a mac (macos 11 or later, intel or apple silicon), open the disk image: it holds take 5, a shortcut to applications, read me first.txt and the take 5 demo song. drag take 5 onto applications. the first time, macos asks you to confirm an app that isn't from the app store: on macos 11 to 14, ctrl control -click take 5 and choose open ; on macos 15 or later, double-click it, click done , then go to system settings > privacy & security and click open anyway . if macos says the app \"is damaged\", read me first has the one line to paste into terminal. on windows (10 or 11, 64-bit), run the installer. it asks whether to install just for you (no administrator password) or for everyone on the computer (needs one), offers a desktop icon, adds take 5 to the start menu, makes song packages (.take5song) and parts (.take5parts) open in take 5, and can start it when it's done. if windows says \"windows protected your pc\", click more info , then run anyway . a newer installer installs over the old version, copying only what changed; if take 5 is open it asks to close it first (take 5 asks about unsaved songs). when take 5 asks to use the microphone (mac), click allow : it can't record without it. if you clicked don't allow, turn take 5 on in system settings > privacy & security > microphone. take 5 opens the song you had open last time. the very first time there's none, so it makes a new one, \"untitled song\", in music/take 5 (a real song folder: keep it or delete it), and a short guided tour starts a second later (see \"take the guided tour\"). if take 5 closed without saving last time, it offers the changes it kept (see \"recover after a crash\"). choose your audio interface or headphones in settings > audio settings... , ctrl+, cmd+, . see \"set up an audio interface\"."],["getting-started--update-take-5-check-for-updates","Update Take 5 (Check for Updates)","Getting started","setting-up.html","update take 5 (check for updates) each time take 5 opens, it first asks the internet whether there's a newer take 5 (in the background). if there is, a window says an update is available , with what's new in it (its release notes: what's new, changed and fixed; scroll for more) and two buttons: install now and close (which leaves it for now). help > check for updates... (on the mac, take 5 > check for updates... ) asks any time: with nothing newer the status line says which version is the latest, and without internet the window says it couldn't check. install now downloads it with a progress bar (cancel stops it) and checks it's exactly the file that was published (its size and fingerprint), so a broken or altered download is never run. then: on windows, take 5 closes (asking about unsaved changes first), the installer runs by itself and take 5 opens again, in a minute or so. your songs and settings stay as they were. on the mac, the disk image opens in finder: quit take 5, drag the new take 5 onto applications (replacing the old one) and open it. the downloaded installer (a few hundred mb) is deleted the next time take 5 opens, once that version (or a newer one) is the one running. the check when take 5 opens says nothing unless there's a newer version; check for updates at startup , next to it, turns it off. which version you have is in help > about take 5 ( take 5 > about take 5 ), with the build it is (\"take 5 v0.17.1\"). the online cheat sheet and manual (alanone.github.io/takefive) links to the latest under its title (windows installer, mac disk image, all releases)."],["getting-started--take-the-guided-tour-tutorial","Take the guided tour (tutorial)","Getting started","setting-up.html","take the guided tour (tutorial) help > tutorial starts a tour of the basics on the song that's open, in 13 steps. it highlights the real controls one at a time: playing and recording, adding a track, a track's controls, plugins, instrument tracks, writing notes, the mixer, recording takes, saving and exporting, and making take 5 your own. do what a step says (it moves on by itself once it's done), or press next ; on the last step it's finish . back goes to the previous step and skip tour ends it. the tour runs on its own the first time take 5 starts, and help > tutorial opens it again any time a song is open. the keys it mentions follow your chosen key commands set. it's safe on a song you care about: the steps that change something (adding a track, writing notes) can be undone with ctrl+z cmd+z ."],["getting-started--find-where-my-songs-are-saved","Find where my songs are saved","Getting started","setting-up.html","find where my songs are saved each song is a folder of its own in your music folder, under take 5 (music/take 5, music\\take 5 on windows). inside it: the song file, ending in .tracktionedit (open this one); audio : every recording and imported file; backups : earlier saves, one at most every 5 minutes, the newest 20 kept ( file > revert to backup lists them by date); snapshots , if you've saved any, and captures , the nam captures and impulse responses copied into the song; a hidden autosave, written every 2 minutes while there are unsaved changes (not while recording), which brings the work back after a crash. recordings always go into the song's audio folder, so the folder can be copied or moved as a whole, or zipped and sent (or use file > save song package... ). file > show song folder opens it in finder (explorer on windows). what isn't in the song lives in take 5's settings (~/library/take 5, %appdata%\\take 5 on windows): song and track templates, layouts, macros, your key commands and the audio settings."],["getting-started--start-a-new-song","Start a new song","Getting started","setting-up.html","start a new song file > new song... , ctrl+n cmd+n , asks where to make the song: it starts in music/take 5 with the name \"new song\". type a name and save; take 5 makes a folder by that name (it won't use a folder that already has files in it). a new song starts at 120 bpm in 4/4, with the click on, a one-bar count-in and one audio track. to start from your own setup instead (the band's tracks, inputs, plugins, buses and routing), make a song the way you like it and choose file > save as song template... : it keeps everything but the clips. then: settings > template for new songs picks the one file > new song starts from; none (one audio track) goes back to the plain song. file > new song from template picks any of them for this one song (greyed when you haven't saved one)."],["getting-started--open-a-song","Open a song","Getting started","setting-up.html","open a song file > open song... , ctrl+o cmd+o , starts in music/take 5: open a song folder's .tracktionedit file, or a song package (.take5song) a bandmate sent you (it's unpacked into music/take 5 first). file > open recent lists the songs you've opened, by name (with the folder too when two have the same name; songs that no longer exist are left out; clear menu empties it). take 5 reopens the last song by itself when it starts. if the song open now has unsaved changes, take 5 asks whether to save them first. double-clicking a song or a package in finder (explorer on windows) while take 5 is open opens it in that window, not in a second take 5. if files the song uses have moved, take 5 says how many are missing: find in folder... looks for them in a folder you choose, later opens the song without them (see \"find files a song is missing\")."],["getting-started--open-the-demo-song","Open the demo song","Getting started","setting-up.html","open the demo song the demo song \"take 5 demo\" plays on take 5's own sounds (the amp, the drum machine, the built-in synth), so it needs nothing else installed. it's a folder like any song's: the song, its audio and the drum kit's samples. on the mac, drag the \"take 5 demo\" folder from the disk image into music/take 5 (where open song starts). on windows the installer puts it in music\\take 5\\take 5 demo. installing again doesn't overwrite a demo you've changed, and uninstalling leaves it. then file > open song... and open \"take 5 demo.tracktionedit\" inside it. play with it freely: to keep the demo as it came, copy its folder first and change the copy, or don't save."],["getting-started--know-the-parts-of-the-window","Know the parts of the window","Getting started","setting-up.html","know the parts of the window the top bars : the transport, with the click volume and count-in at the left; go to start, play and record; loop, punch and the metronome; the display with bar, beat and tick, time, tempo and time signature; the output loudness meter at the right. in the console layout a toolbar, a status line and an info line come under it (see \"work in the console layout\"), and any layout can have them (see \"arrange the top bars\"). in a window too narrow for a row, what doesn't fit goes onto a line under it. track headers (left): name, input, r (arm), m (mute), s (solo), the headphones (monitoring), a (automation), the fader, pan, meter and plugin slots. the ruler and the lanes above the tracks: tempo, sections, chords, lyrics and the reference track. each lane's header (in the track headers' column) shows what it says at the playhead: the time signature and tempo, the section, the chord. hover a header and click its x to hide the lane; view > lanes > tempo lane ( g ), sections lane ( shift+g ), chord lane ( alt+g option+g ) and reference lane ( alt+shift+g shift+option+g ) show and hide them. the tracks with their clips; below or instead of them, the mixer and the midi editor or pitch editor . side panels on the right: the shortcuts, the audio file browser, notes, the assistant, the test checklist, smart controls, modulators and cpu use ( view > panels ). the inspector on the left ( i ): the selected track's and clip's settings (see \"see a track's settings in the inspector\"). the status line at the bottom: at the left, what just happened and hints; at the right, the audio driver and interface, the sample rate, the buffer size (and the delay it makes), the inputs and outputs, and how much of the computer's time the song's audio takes (cpu). click the right half to see which tracks and plugins use the most (see \"find what's eating the cpu\")."],["getting-started--find-any-command-or-shortcut","Find any command or shortcut","Getting started","setting-up.html","find any command or shortcut the menus keep the commands used most at the top level and the rest in submenus by kind: in view , lanes , panels , windows , top bars , zoom and automation ; edit > tools and edit > edit options ; file > export other formats ; track > other new tracks and track > group ; mix > reference track . every command keeps its key wherever it is. view > command palette... , ctrl+shift+p shift+cmd+p : type part of a command's name, the first letters of its words (\"nit\" finds new instrument track) or words from what it does; up/down and return run one, esc closes it. each row shows the command's key, so it's also a way to learn them. commands you've run come first (until take 5 quits); ones that can't run right now are dimmed. a slip in the typing still finds it (\"mxier\", \"metronme\"), and so do its letters in order (\"mxr\"). when no command matches, it suggests the nearest (\"did you mean...\") and up to four of the guide's tasks about what you typed (\"tone3000\" finds the nam captures task), which open in the online manual. it finds commands, not the choices in a list: for a theme, a layout, a display size or a recent song, use its menu. view > panels > shortcuts , ctrl+/ cmd+/ , also in the help menu: the cheat sheet beside the tracks, with every key and every mouse gesture, grouped by area. it follows your key commands set. hover over any button for a tooltip."],["getting-started--bring-a-song-over-from-another-daw","Bring a song over from another DAW","Getting started","setting-up.html","bring a song over from another daw file > import project from another daw... opens an .rpp project, an .als set, a dawproject file (.dawproject, the open format many music apps write), an aaf session (.aaf, which most music apps and video editors can export) or a folder of stems and midi files, as a new song, made in music/take 5 under the original's name. tracks, folders, names, volume, pan, mute, colours, audio clips (copied into the song) and midi come over, plus the starting tempo and time signature. plugins, sends and tempo changes don't, nor automation (except from an aaf; see \"import an aaf session\"). when it's done, a report says what came in and what didn't. things to know: other apps' own project files (.logicx, .ptx, .cpr, .flp, .song, .bwproject and the like) can't be read: take 5 says what to export instead when you choose one (an aaf, a dawproject file, or stems and midi). omf isn't supported: export aaf instead. from an .als set, warped clips come in at their original speed and looped clips play once; return tracks aren't brought over. from an .rpp project, items that were muted come in playing: mute them again. a folder of stems has no tempo in it: set the song's tempo before editing to the grid. while it imports, a window says which file it's copying into the song (a session's audio can be gigabytes, so it can take a while), and stays until the new song is open."],["getting-started--import-an-aaf-session","Import an AAF session","Getting started","setting-up.html","import an aaf session in the other app, export the session or timeline as aaf (choosing aaf where it offers aaf or omf, with the audio embedded or next to the .aaf). in take 5, file > import project from another daw... and pick the .aaf. clips land where they were, with their fades, crossfades, clip gain and clip volume envelopes, track volume and pan (automation too, in the track's lanes), mute, solo and markers. if the session started at a timecode (01:00:00:00, say), the song keeps it: an aaf exported from the song starts there too, so it lines up again in the editor. if the audio isn't next to the aaf, take 5 asks for the folder it's in; for mxf audio, choose the \"mediafiles\" folder on the drive it was recorded to (the mxf audio is converted to wav files in the song's audio folder). the import report lists anything missing."],["audio-and-midi-setup--set-up-an-audio-interface","Set up an audio interface","Audio and MIDI setup","setting-up.html","set up an audio interface connect the interface (and install its driver, if it has one) before opening take 5. open settings > audio settings... , ctrl+, cmd+, . choose the driver and the interface: - on the mac there's one driver (core audio): choose the interface as the output and the input . they can be different devices (the interface's inputs, the mac's speakers), but one device for both keeps them in time. - on windows, choose the audio device type first: asio for most interfaces (see \"use asio on windows\"), else one of the windows audio types. with asio there's one device list for both. tick the input channels you'll record from ( active input channels ) and the output channels you'll listen on ( active output channels ). only ticked channels show up in take 5: an unticked input isn't in the tracks' input menus. pick the sample rate and the audio buffer size (see \"choose a sample rate\" and \"choose a buffer size\"). test plays a short tone (440 hz, a second, at half level) on the active outputs: turn your speakers or headphones down first. the meter next to the input shows its level: make a sound and check it moves. the interface's name shows at the right end of the status line. each ticked input appears in the tracks' input menus; inputs are mono, one per track, unless you make a pair one stereo input (see \"record a stereo source on one track\"). settings are remembered between launches. if the interface is unplugged while take 5 is open, the sound moves to the computer's own output (in the console layout the status line turns amber); plug it back in and choose it again here. there's nothing to set for midi: take 5 listens to every midi keyboard it finds (see \"connect a midi keyboard\"). on the mac, bluetooth midi... at the bottom pairs a bluetooth one."],["audio-and-midi-setup--choose-a-sample-rate","Choose a sample rate","Audio and MIDI setup","setting-up.html","choose a sample rate the sample rate (how many times a second the sound is measured) is set in settings > audio settings... , from the rates the interface offers. 44.1 khz or 48 khz is right for most music: 48 khz is the usual one for video and most interfaces, 44.1 khz the cd's. higher rates (88.2, 96 khz) take more cpu and disk for little you can hear. choose it before recording a song, so every take is at the same rate: a recording made at another rate still plays at the right pitch, but is converted as it plays. exports offer 44.1, 48, 88.2 or 96 khz, starting at the interface's rate."],["audio-and-midi-setup--choose-a-buffer-size-latency-vs-dropouts","Choose a buffer size (latency vs dropouts)","Audio and MIDI setup","setting-up.html","choose a buffer size (latency vs dropouts) the buffer size in settings > audio settings... decides how long the sound takes to get through the computer: the list shows each size with the delay it makes (\"128 samples (2.7 ms)\"). smaller is quicker (better for playing through an amp sim or monitoring a vocal) but works the computer harder; too small gives crackles and dropouts. 128 samples is a good start for recording, 64 or 32 on a fast computer with a good interface; raise it to 512 or 1024 for mixing a big song with lots of plugins. if you hear crackles, raise it one step. on the mac the choices are powers of two (32, 64, 128...), 512 at first; with asio they come from the interface's driver, often set in its own control panel . while recording, transport > low-latency mode helps too (see \"play through plugins with less delay\")."],["audio-and-midi-setup--use-asio-on-windows","Use ASIO on Windows","Audio and MIDI setup","setting-up.html","use asio on windows for the lowest latency on windows, choose asio as the audio device type in settings > audio settings... and your interface's asio driver as the device (it's usually named after the interface, ending in \"asio\"). the interface's own control panel (buffer size and so on) opens from the control panel button there, and reset device restarts it if it stops making sound. asio is built into take 5: nothing extra to install but the interface's own driver. without one, the windows types work with any sound card: windows audio (shared with other apps, about 10 ms), windows audio (low latency mode) , windows audio (exclusive mode) (lower, but no other app can play while take 5 has it) and directsound (the oldest, the slowest). on a typical usb interface, asio at 64 or 128 samples plays without dropouts."],["audio-and-midi-setup--measure-recording-latency-so-takes-line-up","Measure recording latency so takes line up","Audio and MIDI setup","setting-up.html","measure recording latency so takes line up take 5 moves every recording earlier by the delay the interface reports, so takes line up with what you played along to. some interfaces report it wrongly, and a take then sits a few milliseconds late. to correct it exactly: connect a cable from an output of the interface straight to an input. turn monitors, amps and headphones down: the measurement plays clicks out of that output. settings > recording latency... : choose that output ( out of ) and input ( back in on ). under them it says what's applied now: \"not measured: going by what the interface reports\", or the correction measured before. press measure : a short burst of clicks plays and take 5 listens for a second and a half. it shows the round trip and how much more it is than the interface reports, and applies that. the correction is kept for that input (by its name) between launches. measure each input you record from, and again after changing the interface or its driver. if nothing comes back, check the cable, the levels and that both channels are ticked in audio settings (measure is greyed while no input or output is on)."],["audio-and-midi-setup--connect-a-midi-keyboard","Connect a MIDI keyboard","Audio and MIDI setup","setting-up.html","connect a midi keyboard plug in the keyboard (usb, or through the interface's midi in). take 5 finds it by itself within a few seconds, even while it's open, and listens to every midi input it finds: there's nothing to tick. a bluetooth keyboard pairs from bluetooth midi... at the bottom of settings > audio settings... . add an instrument track ( track > new instrument track... , ctrl+alt+s option+cmd+s ) and choose an instrument from the menu. instrument tracks listen to \"all midi ins\", so any connected keyboard plays them. arm the track (its r button) to play it live and record it. no keyboard? use midi > musical typing ( ctrl+k cmd+k ) to play from the computer keyboard: the letters play notes, z and x change the octave, c and v the velocity, and tab holds the sustain. if a keyboard plays some notes twice, see settings > ignore notes sent twice by (\"my keyboard plays some notes twice\")."],["audio-and-midi-setup--send-midi-clock-to-a-drum-machine-or-another-app","Send MIDI clock to a drum machine or another app","Audio and MIDI setup","setting-up.html","send midi clock to a drum machine or another app settings > send midi clock to lists your midi outputs: tick one and it follows take 5's tempo and start/stop (a drum machine plays along in time, an arpeggiator or another app keeps the tempo). tick it again to stop sending. the choice is kept for that output between launches. the option is greyed out when no midi output is connected: plug in the device (or start the other app's virtual midi port: the iac driver in the mac's audio midi setup; on windows, a tool such as loopmidi) and open the menu again. it shows up within a few seconds."],["audio-and-midi-setup--use-bluetooth-headphones-mac","Use Bluetooth headphones (Mac)","Audio and MIDI setup","setting-up.html","use bluetooth headphones (mac) bluetooth headphones are fine for listening but lag too much for recording. opening a bluetooth headset's microphone switches them to a low-quality call mode, so when the output and input are the same bluetooth headset, take 5 records from the mac's built-in microphone instead (or another input if there's none) and the headphones stay in music mode. it does this when take 5 opens and when the headset connects while it's open. for recording, use wired headphones on an interface."],["customising--change-the-look-themes","Change the look (themes)","Customising","setting-up.html","change the look (themes) view > theme : take 5 (the default: a studio look, near-black, with knobs and fader caps that look made, buttons that light up, slots and fields set into the panel, an lcd in soft green), light , graphite (the default before), midnight , slate , stone , charcoal , steel , indigo and ember . light and stone are light; the others are dark. in every dark theme a knob's arc says what it does: amber for level (gain, threshold, drive), blue for time and tone (attack, frequency), teal for blends (mix, width). in every theme a plugin slot's light is green when it's on, red when it's off (bypassed), and amber with a \"!\" if it crashed. everything switches (tracks, mixer, editors, panels, menus, the window's title bar); the song stays open. the theme is remembered between launches and is the same in every layout (a layout doesn't change it). a theme only changes the look: the keys are in settings > key commands... and the arrangement of the window in view > layouts , so steel with the console layout and set d's keys is three choices."],["customising--make-everything-bigger-or-smaller","Make everything bigger or smaller","Customising","setting-up.html","make everything bigger or smaller view > display size : 90%, 100% (the default), 110%, 125% or 150%. everything scales and stays sharp; remembered after a relaunch. useful on a big screen, from across the room, or for tired eyes. on a small laptop screen 90% fits more tracks and plugin slots. for taller or shorter tracks only, use view > zoom > taller tracks / shorter tracks , ctrl+↑ cmd+↑ / ctrl+↓ cmd+↓ : in steps of 20 points, between 60 and 280. the track height is kept with the layout."],["customising--use-another-daw-s-shortcuts","Use another DAW's shortcuts","Customising","setting-up.html","use another daw's shortcuts settings > key commands... : under \"key set:\", choose take 5 (the default) or set b to set f , other sets of keys people know from elsewhere; the line under it shows the set's main keys (play, record, split, undo), so pick the one you recognise. then change any single shortcut: click + to add a key, click a key to change or remove it. a key another command already has asks first ( re-assign moves it). a note under the list warns when a key is one the system takes first, so it would never reach take 5 (on the mac, command- space for spotlight or control+arrows for spaces; on windows, alt+f4, ctrl+esc and the like). the cheat sheet, tooltips, menus and tutorial follow your keys. things to watch: choosing another key set replaces your single changes with that set's keys, and reset to defaults goes back to take 5's keys (after asking; \"key set\" then says take 5). your keys are kept in take 5's settings, for every song."],["customising--arrange-the-screen-layouts-and-panels","Arrange the screen (layouts and panels)","Customising","setting-up.html","arrange the screen (layouts and panels) view > layouts : built-in arrangements (default; browser, the browser on the right and the mixer in place of the tracks; edit and mix, no panels and the midi editor in its own window; compact, like browser with shorter tracks; mixer below; console; browser and mixer; floating windows, the mixer and the editor each in a window; recording, big tracks; mixing, the mixer full size), save current layout... for your own, and delete saved layout . a layout keeps: the side panels open and their order, whether they float or sit side by side, the mixer (shown or not, and where), the midi editor floating or not, which lanes show, the track height, the inspector, the console layout and the top bars' arrangement, the floating windows' places and the sizes of the panes. it doesn't change the theme, the display size or the keys. the default layout opens the shortcuts panel; the console one also turns on view > top bars > console layout , the inspector and the audio file browser. things to watch: choosing a built-in layout also puts its lanes and track height back; saving under a name you've used replaces that layout; delete saved layout doesn't ask first. side panels ( shortcuts , audio file browser , notes , assistant , test checklist , smart controls , modulators , cpu use , in view > panels ) each open and close on their own key; several open at once stack on the right, one above another (drag the edge between two to share the height). view > windows > side panels side by side puts them in columns; view > windows > side panels in own windows floats them all (or, when they all float, puts them back). esc closes the panel or window you're working in, as its close button would: a side panel or the inspector (once you've clicked in it, typing in its text box too), a panel in its own window, a plugin's window, the tuner and the other small windows, a dialog. a plugin's own controls may keep esc to themselves: click the window's title bar first. while exporting, esc in the export window cancels. view > windows > mixer in place of tracks , mixer below tracks and mixer in own window say where the mixer goes; midi editor in own window floats the midi editor. drag the edge between panes (tracks and mixer, the editor, the side panels, the track headers' right edge) to resize; double-click an edge for its default size. the track headers are 240 to 600 points wide (300 at first). sizes are kept between launches and in saved layouts."],["customising--arrange-the-top-bars-customize-top-bars","Arrange the top bars (Customize Top Bars)","Customising","setting-up.html","arrange the top bars (customize top bars) the top of the window is made of blocks: the click and count-in, the transport's buttons, loop, punch and metronome, the position display (position, time, tempo, signature), the loudness, and the toolbar's undo and redo, m s l r w a , follow, the tools, snap and grid with q , the output level, the zones, the status line and the info line. put them where you like, in up to four rows: view > top bars > customize top bars... (or right-click an empty part of the bars). each block gets an outline, and a strip under the bars says how. drag a block to move it: let go in the left, middle or right third of a row to put it at that row's left, in its middle or at its right (a line shows where it lands among the blocks there); let go under the last row to start a new row. a row you empty goes. right-click a block to hide it; show a block... brings a hidden one back (at the end of the last row). reset goes back to the layout's own arrangement. done . the arrangement is kept with the layout: save it with view > layouts > save current layout... to have it as a layout of your own. view > top bars > toolbar , status line and info line hide those blocks, or bring them back on a row of their own, in any layout. in a window too narrow for a row, what doesn't fit goes onto a line under it."],["customising--work-in-the-console-layout","Work in the Console layout","Customising","setting-up.html","work in the console layout view > top bars > console layout (or view > layouts > console , which also opens the inspector, the audio file browser and the mixer below the tracks, at a track height of 90) arranges the window around a toolbar and a console-style mixer, with any theme ( view > theme > steel suits it). choose it again to go back to take 5's own. the toolbar , under the transport, across the window. at the left: undo and redo; m (lit when a track is muted: click to unmute them all), s (the same for solos), l (the listen bus), r (every track reads its automation), w (every track writes it, in touch; again, back to read), a (the next track with automation); following the playhead. in the middle: the tools (pointer, marquee, scissors, glue, mute, zoom, draw, play); snapping on or off with its grid; q to quantise. at the right: the output's level and the zones: the inspector, the mixer below the tracks, the side panels. (where the playhead is shows in the transport above.) in a narrow window the middle moves over, and what doesn't fit is left out. the status line under it, across the window: whether the audio inputs and outputs are connected (amber when not), the listen bus, how long can be recorded on the song's disk, the record format, the pan law and the buffer size. click one to change it (audio settings, the listen bus). the info line under that, across the window in pills like the status line's: the selected clip's name, start, end, length, fades, volume and mute; with no clip selected, the selected track's name, volume, pan, mute and solo; a hint when nothing is. several selected: how many, and the first one's. click a value to type a new one, as in the inspector; click mute or solo to switch it. hide any of these three rows with view > top bars > toolbar , view > top bars > status line and view > top bars > info line ; the tracks get the room. to move their blocks around (or onto the transport's row, or into take 5's own layout), see \"arrange the top bars\". they're kept with the layout. track headers : the track's number, m s, its name and level on top; under them record, monitor, r and w (this track's automation read, or written in touch), e (its settings, in the inspector) and a (its automation lanes); a picture of what it is; the meter down the right edge. the mixer : under each name a routing section (its input and output); pre , the channel's input stage: ø (polarity), its input gain (-24 to +24 db) and a low cut (20 hz to 2 khz) and a high cut (1 to 20 khz), 12 db an octave, each switched on with lc or hc , before any plugin; then inserts and sends , each with a switch that turns all of them on or off at once and, for the inserts, the delay their plugins add (in ms); pan and width as bars; e beside m and s. the mixer's title bar has configurations (save how the mixer looks under a name, and recall it), racks (which of routing, pre, inserts and sends the strips show), narrow / wide strips (more fit when narrow), q-link (lit: moving a fader, pan, mute or send on one of the selected channels moves the others too, as mix > link selected channels ), and m and s to unmute and unsolo everything."],["customising--run-several-commands-from-one-key-macros","Run several commands from one key (macros)","Customising","setting-up.html","run several commands from one key (macros) settings > macros... : new makes one (\"prepare a vocal track\"), rename... and delete change the list. with a macro chosen, add a command... adds any command to it (from a list by menu: new track, arm track, input monitoring, channel strip...), in order; move up , move down and remove change its order, run tries it. set key... opens key commands , where the macros are under macros : give it a key there. then the key (or settings > run macro , greyed until there's a macro) runs its commands one after another. a command that can't run at that moment (arm track with no track selected, say) is skipped, and the status line says how many of them ran. a macro can't run another macro. macros are kept in the app's settings, for every song."],["customising--make-stop-go-back-to-where-i-started-playing","Make stop go back to where I started playing","Customising","setting-up.html","make stop go back to where i started playing settings > stop returns to where play started : when on, stopping puts the playhead back where playing started; off (the default), it stays where it stopped. transport > go to start , return or home , always goes to the start. handy for playing the same passage again and again while mixing or rehearsing a part. after a scrub (playing while you drag the playhead), stop leaves it where it is. the setting is kept between launches."],["recording--record-a-guitar-or-vocal","Record a guitar or vocal","Recording","recording.html","record a guitar or vocal choose your interface in settings > audio settings... . add an audio track ( + track ). it takes the first input no other track uses; pick another from the input menu in its header. an input feeds one track at a time: choosing it on a track takes it off the one that had it. arm it with its r button. its meter now shows the input level: play as loud as you will and check it stays clear of the top. too hot clips the recording for good, so set the level on the interface's gain knob, not the track's fader (the fader changes what you hear, not what's recorded). turn the click on ( k , or the metronome button) and choose a count-in in the transport bar. a new song starts with both on: the click, and a count-in of one bar. press r (or the record button) to record, and space (or r again) to stop. the waveform draws as you record. the take is a 24-bit wav file at the interface's sample rate, named after the track (\"vocal_take_3.wav\"), in the song's audio folder, and the song is saved after each take: the status line says \"take recorded and saved\" (or what went wrong). recording over an old take replaces it where they overlap, but the old one is kept as a take (see \"comp the best parts of several takes\"); midi on an instrument track works the same way. recording over a clip that wasn't recorded (an imported file, or notes you drew) cuts it where they overlap, and only undo brings that part back. if the song has lyrics, the lyrics prompter opens when recording starts. in the console layout the status line shows the record format and how long you can record on the song's disk."],["recording--hear-myself-while-recording-input-monitoring","Hear myself while recording (input monitoring)","Recording","recording.html","hear myself while recording (input monitoring) the headphones button in a track's header sets input monitoring. click it to go through auto (you hear the input while the track is armed, playing or stopped), on (always) and off (never, for when the interface's own direct monitoring is on; the button is drawn faint). with monitoring on, the input goes through the track's plugins, so you can play through an amp sim. if what you hear is delayed, lower the buffer size or turn on transport > low-latency mode . monitoring belongs to the input, not the track: it goes with the input to another track and to other songs, and is kept between launches. the button is greyed out while the track has no input. hearing yourself twice, with a slight echo? direct monitoring on the interface is on too: turn one of them off."],["recording--record-several-inputs-at-once-a-band","Record several inputs at once (a band)","Recording","recording.html","record several inputs at once (a band) tick all the inputs in settings > audio settings... , then track > other new tracks > new tracks for unused inputs to get a track for each, or set each track's input by hand. arm them all: shift -click an r arms the selected tracks too (and disarms them, when it disarms), ctrl cmd -click arms every track, and track > arm all tracks / disarm all tracks do it from the menu (tracks without an input, and buses, are left out). press r : each input records onto its own track, all starting at the same moment, so they stay in time with each other."],["recording--record-a-stereo-source-on-one-track-stereo-inputs","Record a stereo source on one track (stereo inputs)","Recording","recording.html","record a stereo source on one track (stereo inputs) inputs are mono, one per track, which suits guitars and mics. for something stereo (an amp modeller's two outputs, keys, a pair of overheads), open an audio track's input menu and choose make input 1 + input 2 one stereo input (or 3 + 4, and so on: always an odd one and the next, never 2 + 3): the pair becomes one input, \"input 1 + 2\", that track records from it, and its takes are stereo files. make input 1 + 2 two mono inputs in the same menu splits it again. the pairs are a setting of this computer, as the inputs are the interface's: a pair made stereo is stereo in every song, and another track that was on input 1 or 2 has no input afterwards (the status line says which)."],["recording--use-the-metronome-and-count-in","Use the metronome and count-in","Recording","recording.html","use the metronome and count-in transport > metronome , k , or the metronome button (in the transport, beside loop and punch) turns the click on or off. the click slider at the left of the bar is its volume (it goes quiet but never silent: turn the click off for that). count-in (beside the click slider): no count-in, 1 beat, 2 beats, 1 bar or 2 bars of clicks before recording starts (a bar as the song's first time signature has it). it plays only when you record from stopped: pressing r while playing starts recording at once. transport > click sound : classic (the default), woodblock, beep, cowbell, hi-hat, claves, side stick, tambourine or shaker; the first beat of the bar is higher or louder. the sound is the same in every song. transport > click only when recording : no click on playback. transport > click output : send the click to another output (for example only the drummer's headphones) instead of the main outputs . the click's volume, output and click only when recording are kept with the song. the click is never in an export."],["recording--punch-in-to-fix-a-part","Punch in to fix a part","Recording","recording.html","punch in to fix a part drag in the ruler over the part to fix: that sets the punch (and loop) range, drawn in the ruler. the drag doesn't snap to the grid. turn on the punch button (red) in the transport bar. loop and punch can't be on together, so turning one on turns the other off. arm the track, start playing before the range and press r (or start recording early): only the punched part is replaced; the rest of the old take stays, and the replaced part is kept as a take. transport > pre-roll for punch-in (off, 1 bar, 2 bars) starts recording that many bars before the punch-in, wherever the playhead is, so you can play yourself in (a count-in plays before that). without pre-roll, recording from past the range starts a second before the punch-in. the pre-roll is kept with the song."],["recording--record-several-takes-in-a-loop","Record several takes in a loop","Recording","recording.html","record several takes in a loop drag in the ruler to set a range (longer than 2 seconds: a shorter one doesn't record), turn on looping with transport > loop , c , or the loop button, arm the track and record. recording always starts from the start of the loop. each pass becomes a take of its own, on audio and instrument tracks alike; stop when you have enough. the track plays the last complete pass (a pass you stopped part way through is kept as a take too), and its takes button shows them all for comping. transport > set loop to selection , ctrl+u cmd+u , loops over the selected clips or a marquee range instead (and turns punch off)."],["recording--keep-something-i-played-without-recording-capture-recording","Keep something I played without recording (Capture Recording)","Recording","recording.html","keep something i played without recording (capture recording) take 5 keeps what you play even when not recording: a midi keyboard's notes, and the last minute of every input a track in the song uses. select the track and choose transport > capture recording , shift+r : it appears as a clip named \"captured\". on an instrument track you get the notes (not the sustain pedal or other controllers); on an audio track, what came in on its input: the last performance, from after its last pause of 4 seconds or more, saved in the song's audio folder (it isn't a take). played along with the song, it lands where you played it (for a loop, the last pass); played while stopped, it goes at the playhead with your timing. it replaces whatever is under it on the track. with no track selected, it goes on the armed track (an instrument track first), or the first instrument track for notes. undo takes it away."],["recording--play-through-plugins-with-less-delay-low-latency-mode","Play through plugins with less delay (low-latency mode)","Recording","recording.html","play through plugins with less delay (low-latency mode) some plugins delay the sound to do their work (look-ahead limiters, linear-phase eqs and the like), and take 5 delays everything else to match, so playing through them feels late. transport > low-latency mode switches off (bypasses) every plugin on the tracks and the master that delays the sound by more than 3 ms, so what you hear while playing is immediate; the status line says how many. turn it off again to bring exactly those plugins back. it's kept with the song, so turn it off before mixing: while it's on, those plugins stay off for playback. an export always has every plugin on, low-latency mode or not (its message says so). plugins you add while it's on aren't switched off."],["recording--tune-my-guitar-or-bass","Tune my guitar or bass","Recording","recording.html","tune my guitar or bass transport > tuner , alt+t option+t , or right-click an audio track > tuner... to tune on that track's input. choose the input (its meter shows it's hearing you), the instrument (guitar, 7-string guitar, 8-string guitar, bass, 5-string bass, 6-string bass, or chromatic for anything) and a tuning (standard, half or whole step down, drop d, c#, c or b, dadgad, open d, e, g or c, and the 7- and 8-string and bass ones: drop a, drop e, bass drop d, bead, high c...). play a string: the string is found by itself (or click one to tune only it; auto goes back to finding it), its note and cents show, and the pill says tune up , tune down or in tune (within a cent); a string gets a tick once it's stayed in tune for half a second. needle or strobe switch the view: the strobe turns one way when the string is sharp and the other when it's flat, faster the further out, and stands still when it's in tune, which shows the last cent better than the needle. capo (0 to 12 frets) and a reference pitch other than a = 440 hz (415 to 466) are at the bottom; new tuning... in the tuning list takes your own as notes (\"d a d g b e\"), and delete this tuning removes one. mute speakers silences the song while tuning, until the tuner closes. the input, view and your tunings are kept between launches."],["recording--reamp-a-di-through-a-real-amp","Reamp a DI through a real amp","Recording","recording.html","reamp a di through a real amp record a clean di first, then play it out to a real amp later and record the amp: right-click the di track > reamp... . choose the output your reamp box is on (it starts on the di track's output) and the input the amp's mic comes back in on. press measure once (with the amp turned down, or a cable from the output straight to the input): it measures how late the sound comes back, as settings > recording latency... does, and keeps that for the input on this computer. set up reamp : the di track's output goes to the reamp output (so it leaves the main mix), and a \"<track> reamp\" track appears under it, armed on the mic's input. record it: the reamped take lines up with the di to the sample. for pedals or outboard gear on a track as it plays, use the hardware insert built-in effect instead."],["recording--make-a-headphone-mix-for-each-player-cue-mixes","Make a headphone mix for each player (cue mixes)","Recording","recording.html","make a headphone mix for each player (cue mixes) turn on more outputs in settings > audio settings... (for example outputs 3 and 4 for a headphone amp). track > other new tracks > new cue mix... makes a mix for one player on an output of its own: give it a name (\"cue: drums\" to start with) and an output. it starts like the main mix (each track's send at its fader level) and is fed by pre-fader sends (marked \"pre\" in the mixer), so its levels change without touching the main mix, and the main mix's faders don't change it. turn up what a player wants more of (\"more me\") on that cue mix's sends. only the tracks there when it's made get a send: give a track added later one with its + send . to send the click to only that output, use transport > click output ."],["recording--talk-to-the-band-in-their-headphones-talkback","Talk to the band in their headphones (talkback)","Recording","recording.html","talk to the band in their headphones (talkback) set up a mic at the computer once: transport > talkback settings... has the mic it's on (its meter shows it's the right one) and its level in the headphones (-40 to +12 db; double-click for 0 db). then transport > talkback , y , talk in that window or on the mixer's master strip turns it on until you press it again: the mic goes into every cue mix (headphone mix), never the speakers, the song or an export. while recording it's turned down 20 db, so a word during a take doesn't drown the players (the button says so). it needs cue mixes on outputs of their own (see \"make a headphone mix for each player\"), not shared with the main outputs; the window says which ones it reaches. the mic and level are kept for this computer; talkback itself starts off."],["takes-and-comping--see-all-the-takes-on-a-track","See all the takes on a track","Takes and comping","recording.html","see all the takes on a track once a track has a recording, its header gets a takes button with the number of takes (\"takes 3\"). click it to show or hide the take lanes under the track: each take (\"take 1\", \"take 2\"...) on its own lane, wherever on the track it was recorded, the parts used in the comp shown bright. midi recordings get take lanes too, shown as notes. whether a track's lanes show is kept with the song."],["takes-and-comping--comp-the-best-parts-of-several-takes","Comp the best parts of several takes","Takes and comping","recording.html","comp the best parts of several takes show the take lanes with the track's takes button. drag across a take lane over the part you like: that part of that take goes into the track (the comp). the drag snaps to the grid; hold ctrl cmd while dragging to ignore it. click a take lane to use the whole take. do this for each phrase until the comp is right; each choice is undoable. comped pieces are ordinary clips with short crossfades (10 ms; none between midi pieces), so you can trim or fade them like any other clip. moving all of a comp's clips, even to another track, moves the takes with them. on tracks in an edit group (a drum kit's mics), choosing a take on one chooses it on all of them, so the kit stays in phase."],["takes-and-comping--delete-a-take-i-don-t-want","Delete a take I don't want","Takes and comping","recording.html","delete a take i don't want hover over a take's name in the take lanes and click its x, or right-click the take > delete take (and the comp's pieces of it) . right-click > use whole take puts all of it in the comp. deleting a take also removes the pieces of it that were in the comp, so check the comp afterwards. ctrl+z cmd+z brings it back. the take's file stays in the song's audio folder ( file > clean up unused audio... removes files nothing uses)."],["takes-and-comping--turn-a-comp-into-one-clip-flatten-comp","Turn a comp into one clip (Flatten Comp)","Takes and comping","recording.html","turn a comp into one clip (flatten comp) right-click the track > flatten comp (greyed until the track has two or more clips): everything on the track, from its first clip's start to its last clip's end, becomes one clip named \"comp\" that sounds the same, its audio a new file (\"<track> comp.wav\") in the song's audio folder. the track's plugins and fader stay on the track. the takes are still there to comp again, and ctrl+z cmd+z puts the comp back. for midi, the comped clips are merged into one."],["takes-and-comping--put-each-take-on-its-own-track-takes-to-tracks","Put each take on its own track (Takes to Tracks)","Takes and comping","recording.html","put each take on its own track (takes to tracks) right-click a track with two or more takes > takes to tracks : a copy of the track for each take appears under it (\"<track> - take 2\"), with the same plugins and fader but no input, each playing its take. the original keeps its comp. useful for doubling a part, or comparing takes in the mixer."],["takes-and-comping--tidy-midi-takes-automatically-after-recording","Tidy MIDI takes automatically after recording","Takes and comping","recording.html","tidy midi takes automatically after recording midi > align midi takes after recording (off at first) gives each midi take a gentle quantise as soon as it's recorded, keeping the feel: notes close to the grid move 60% of the way to it (the snap grid, with its swing or groove; 1/64 with snapping off), the rest stay, and lengths don't change. each pass is tidied before it's kept as a take, so choosing a take again from its lane gives the tidied notes too. the setting is saved with the song. turn it off to keep takes exactly as played. to tidy a part by hand later, open it in the midi editor and use midi > align notes or the quantise button."],["tracks--add-an-audio-track","Add an audio track","Tracks","editing-and-arranging.html","add an audio track click + track at the top of the track headers (beside the feel and snap boxes), or track > new audio track , ctrl+alt+n option+cmd+n . an audio track records from one input (a guitar, a mic) or holds audio files. the new track goes at the end, named \"audio 1\", \"audio 2\"..., with the next colour, and takes the first input no other track uses (or none: pick one in its input menu). track > other new tracks > new tracks for unused inputs adds a track for every input that hasn't got one, for recording a band. adding a track is one undo step."],["tracks--rename-colour-reorder-or-delete-tracks","Rename, colour, reorder or delete tracks","Tracks","editing-and-arranging.html","rename, colour, reorder or delete tracks rename: double-click the track's name (or right-click the header > rename ). colour: right-click the header > colour , one of eleven (blue first, grey last). track > colour tracks by instrument colours every track, and gives it a picture, from what its name says it is (kick, bass, vocal...). reorder: drag a header up or down; a line shows where it goes. several selected tracks move together. the same works in the mixer, dragging a strip by its name. delete: right-click the header > delete track , or select tracks and press delete. deleting and moving are each one undo step. select tracks: click a header; shift -click or ctrl cmd -click adds or removes tracks. a right-click acts on the selected tracks when the one you click is among them, else on that one alone. height: view > zoom > taller tracks / shorter tracks , ctrl+↑ cmd+↑ / ctrl+↓ cmd+↓ : all tracks, in steps of 20 points, between 60 and 280."],["tracks--group-tracks-into-a-folder-a-drum-bus","Group tracks into a folder (a drum bus)","Tracks","editing-and-arranging.html","group tracks into a folder (a drum bus) select the tracks and choose track > group > group into folder , ctrl+shift+d shift+cmd+d , or right-click a header > group selected tracks into folder . the folder, named \"folder\", takes the first track's place. a folder is also a group bus: everything inside plays through its fader, pan, mute and plugins (put the drum bus compressor there). click its chevron to collapse or expand it (collapsed, it shows a mini row per track). drag a track onto the middle of a folder's header to put it in, or onto its top or bottom edge to put it above or below. right-click the folder > ungroup folder removes the folder and keeps the tracks where it was. track > group > group into vca is the other kind: a folder whose fader moves its tracks' levels without mixing them through it (see \"move several faders together\"). grouping and ungrouping are one undo step each."],["tracks--copy-tracks-with-all-their-settings","Copy tracks with all their settings","Tracks","editing-and-arranging.html","copy tracks with all their settings select track headers and edit > copy , ctrl+c cmd+c , then edit > paste , ctrl+v cmd+v : new tracks after the last selected one (in its folder, if it's in one; at the end with none selected), with the same input, plugins and their settings, automation, fader, pan, mute, sends and colour, but no clips. edit > paste tracks with clips , ctrl+shift+v shift+cmd+v , brings the clips too. copying a folder brings its tracks. an input feeds one track at a time, so a copy only gets the input if no other track uses it. each paste is one undo step."],["tracks--save-and-reuse-a-track-setup-track-templates","Save and reuse a track setup (track templates)","Tracks","editing-and-arranging.html","save and reuse a track setup (track templates) right-click a track's header > save as track template... and name it: its plugins and their settings, automation, fader, sends, colour and input are saved, not its clips (a guitar track with your amp sim, a vocal chain). with several tracks selected (including the one you right-click), or a folder, they're saved together. in any song, track > other new tracks > new track from template adds them. templates are kept with take 5, not the song, so every song can use them. for whole-song setups, see \"start songs from a template\"."],["tracks--try-different-versions-of-a-track-alternatives","Try different versions of a track (alternatives)","Tracks","editing-and-arranging.html","try different versions of a track (alternatives) right-click an audio or instrument track > alternatives keeps several versions of a track's clips to switch between, on the same plugins, settings and automation (only the clips differ): new alternative (empty) starts a blank one (\"alt 2\"...) to record a different part. duplicate as new alternative copies the current clips to edit. picking a name switches to it. the first is \"main\". rename... , and delete this alternative (its clips go with it; greyed for the last one). once a track has two or more, its header shows which one is playing. alternatives are saved with the song and undoable. a bandmate's version of a part arrives as an alternative named after them."],["tracks--show-only-some-tracks-in-a-big-session-hide-tracks-track-sets","Show only some tracks in a big session (hide tracks, track sets)","Tracks","editing-and-arranging.html","show only some tracks in a big session (hide tracks, track sets) the button at the bottom of the track headers (it says \"all 75 tracks\", or \"14 of 75 tracks shown\", lit while any are hidden) and view > show tracks choose what's shown in the tracks and the mixer: show all tracks brings every one back (also view > show all tracks ). under show only , the sets, each with how many tracks: your own, then ones made from the song: each folder's tracks, and tracks grouped by what their names say they are ( drums : kick, snare, toms, hats, overheads, rooms...; bass , guitars , keys , vocals , and buses and fx ; each only when two or more tracks fit). one click shows just those. show only the selected tracks and hide the selected tracks ; or right-click a track > hide track . save what's shown as a set... names what's shown now (a name you've used replaces that set; \"drums\" of your own wins over the one made from the names); delete a saved set takes one away. hidden tracks still play and are in exports: hiding only tidies the view. what's hidden and your sets are kept in the song; showing and hiding aren't undo steps. hiding a folder hides what's in it; showing a track in a folder shows the folder too."],["tracks--keep-a-track-in-view-while-scrolling-pin-it","Keep a track in view while scrolling (pin it)","Tracks","editing-and-arranging.html","keep a track in view while scrolling (pin it) right-click a track > pin to the top (stays in view) : it moves above the other tracks, under a line, and stays there while they scroll (a lead vocal while editing the band, a guide track). unpin puts it back in its place. pinning is kept in the song, and isn't an undo step."],["tracks--find-what-s-eating-the-cpu-cpu-use","Find what's eating the CPU (CPU Use)","Tracks","editing-and-arranging.html","find what's eating the cpu (cpu use) click the cpu reading at the bottom right of the window, or view > panels > cpu use , and play the song: a window lists each track's share of the audio's time (and the master's), the busiest first, with each of its plugins that uses any under it, and a bar for each (red when one takes a quarter of the time alone). it updates three times a second while playing; nothing is measured while the song is stopped. double-click a plugin to open it; right-click it to bypass it (or turn it back on ), freeze its track or deactivate the track (see below)."],["tracks--free-up-cpu-by-deactivating-or-freezing-a-track","Free up CPU by deactivating or freezing a track","Tracks","editing-and-arranging.html","free up cpu by deactivating or freezing a track right-click a track > deactivate track : its plugins are unloaded (a plugin running in its own process is closed) and the track is silent, greyed out and left out of exports, its settings kept. activate track brings it back exactly as it was. deactivating a folder takes its tracks with it. undoable. use it for a track you're not using now but want to keep. right-click > freeze : the track's clips are recorded through its plugins as they sound and the plugins switched off; it still plays, from the recording. its fader, pan and sends stay live (move them freely). the header says frozen . if you change its clips or plugins it turns to an amber changed : choose freeze again (it's changed since) . unfreeze brings the plugins back. use it for a finished track with heavy plugins. only audio and instrument tracks freeze; drum channel tracks (and a drum machine split into them) can't."],["tracks--write-notes-for-a-song-or-a-track","Write notes for a song or a track","Tracks","editing-and-arranging.html","write notes for a song or a track view > panels > notes , ctrl+alt+p option+cmd+p , opens a side panel with the song's notes (lyrics, ideas, what's left to do) and the selected track's notes (mic, amp settings, which take to keep; the box waits until a track is selected). they're saved with the song as you type (not undo steps)."],["editing-audio--select-move-and-copy-clips","Select, move and copy clips","Editing audio","editing-and-arranging.html","select, move and copy clips click a clip to select it; shift -click adds or removes clips. drag across empty lane space to select clips on several tracks (shift adds). drag a clip to move it, also onto another track: an outline shows where it lands. several selected clips move together. the clip's start lands on the grid (a clip that was off the grid jumps onto it); hold ctrl cmd while dragging to ignore the grid. a clip can't go before the start of the song. edit > copy / cut / paste , ctrl+c cmd+c / ctrl+x cmd+x / ctrl+v cmd+v : paste goes at the playhead, on the tracks the clips came from, and replaces what was there. edit > select all , ctrl+a cmd+a , selects every clip. edit > delete , backspace or delete, removes them (selected tracks too). a clip moved over another wins: the one underneath is trimmed back to a 10 ms crossfade (a midi clip cut exactly, with no crossfade), or removed if it's almost all covered."],["editing-audio--split-a-clip","Split a clip","Editing audio","editing-and-arranging.html","split a clip put the playhead where to cut, select the clip and edit > split at playhead , ctrl+t cmd+t . or choose the scissors tool (press t for the tool menu) and click the clip where to cut. with edit > edit options > snap edits to zero crossings on (it is by default, and kept with the song), cuts and trims land where the waveform crosses zero (within 5 ms), so they don't click; each selected clip at its own crossing. clips that are stretched, reversed, looped or pitch-shifted are cut exactly where asked. the two halves meet exactly, with no crossfade. with the scissors, clicking a selected clip cuts all the selected clips there."],["editing-audio--trim-the-start-or-end-of-a-clip","Trim the start or end of a clip","Editing audio","editing-and-arranging.html","trim the start or end of a clip drag a clip's left or right edge. trimming follows the snap grid (hold ctrl cmd , to ignore it) and, with edit > edit options > snap edits to zero crossings on, lands on a zero crossing. trimming only hides audio: drag the edge back out to get it back (as far as the recording goes; a clip can't be shorter than 10 ms). trimmed over a neighbour, the trimmed clip wins and the neighbour is cut back to a 10 ms crossfade. the trim edges are the outer few pixels of a clip (a very narrow clip has none: zoom in). to slide the audio inside a clip without moving the clip, see \"nudge, repeat and slip clips\"."],["editing-audio--add-fades-and-crossfades","Add fades and crossfades","Editing audio","editing-and-arranging.html","add fades and crossfades drag the fade handle at a clip's top-left or top-right corner (just under the name) to fade in or out. right-click the clip > fade in shape / fade out shape : linear, fast (convex), slow (concave) or s-curve; choosing a shape on a clip without a fade gives it a beat-long one (at most a third of the clip). fade drags don't snap, and a clip's fade in and fade out together can't be longer than the clip. only audio clips have fades. fade lengths can also be typed in the inspector ( i ). overlapping clips crossfade by themselves (10 ms; drawn as an x); drag the later clip's fade-in handle at the join to make the crossfade longer: it stays centred on the join, as long as there's audio either side, and the status line shows its length."],["editing-audio--change-a-clip-s-volume-clip-gain-or-normalise-it","Change a clip's volume (clip gain) or normalise it","Editing audio","editing-and-arranging.html","change a clip's volume (clip gain) or normalise it right-click an audio clip > gain : +6, +3, +1, -1, -3 or -6 db, normalise (to -0.1 db) or reset to 0 db (the menu shows the gain now: \"gain (-3.0 db)\"). normalise sets the gain from the loudest sample in the part the clip plays (fades and envelope aside), each selected clip on its own. clip gain goes from -60 to +24 db; type it, or drag it (-24 to +24), in the inspector. the clip's gain shows in its name strip after the name. settings in the clip menu apply to every selected audio clip (midi clips in the selection are left alone)."],["editing-audio--draw-a-volume-or-pan-envelope-on-a-clip","Draw a volume or pan envelope on a clip","Editing audio","editing-and-arranging.html","draw a volume or pan envelope on a clip right-click an audio clip > volume envelope (or pan envelope ): a line over the clip. click the line to add a point, drag points to shape it (the status line shows the value; points don't snap and can't pass their neighbours), alt option -click a point to remove it. volume goes from silence up to +6 db, on a scale like a fader's; pan has left at the top. the envelope moves and copies with the clip. the envelope commands act on the clip you right-click; clear envelopes removes both from every selected clip."],["editing-audio--nudge-repeat-and-slip-clips","Nudge, repeat and slip clips","Editing audio","editing-and-arranging.html","nudge, repeat and slip clips edit > nudge left / nudge right , alt+← option+← / alt+→ option+→ : move the selected clips one grid step (10 ms with the grid off); never before the start. their automation goes with them when edit > edit options > automation moves with clips is on. edit > repeat , ctrl+r cmd+r : a copy of the selection right after it (several clips keep their layout), selected, replacing what's there; press again for more. slip: alt+shift option+shift -drag a clip to move the audio inside it while the clip stays put (not snapped, and only as far as the recording goes). loop: drag the right end of a clip's name strip (its top-right corner) to repeat the clip as a loop, on the grid; right-click > unloop puts it back to one pass."],["editing-audio--use-the-snap-grid-triplets-and-swing","Use the snap grid, triplets and swing","Editing audio","editing-and-arranging.html","use the snap grid, triplets and swing the snap box above the track headers (\"snap: beat\" to start with) sets the grid for moving, trimming and nudging: off, bar, beat, 1/8, 1/16, or the triplets 1/4 t, 1/8 t, 1/16 t. hold ctrl cmd while dragging to ignore it. the feel box next to it is straight , swing 54, 58, 62, 66 or 70% (on the beat, 1/8 and 1/16 grids; bars and triplets don't swing), or a groove from a played part (right-click a midi clip, or an audio clip, > use as groove ; it applies when its grid is the snap grid). snapping and quantising follow the feel. the lines in the tracks (and the ticks in the ruler) are the snap grid's own: a line at every place a drag can land, swing included, bars strongest, then beats, then the steps between them. zoomed out, where they'd crowd together, only the beats are drawn, then only the bars. with the grid off, bars and beats show; on bar, only bars."],["editing-audio--use-the-edit-tools-pointer-marquee-scissors-glue-mute-zoom-draw-play","Use the edit tools (pointer, marquee, scissors, glue, mute, zoom, draw, play)","Editing audio","editing-and-arranging.html","use the edit tools (pointer, marquee, scissors, glue, mute, zoom, draw, play) press t ( edit > tools > tool menu ) to choose what the mouse does in the tracks: pointer tool (select, move, trim and fade), marquee tool (select a range of time across tracks), scissors tool (click a clip to split it), glue tool (click the selected midi clips to join them), mute tool (click a clip to mute or unmute it; muted clips are dimmed), zoom tool (click to zoom in there, alt option -click to zoom out, drag across what you want to fill the view), draw tool (drag across an empty part of an instrument track: a midi clip that long, on the grid) and play tool (hold the mouse down anywhere in the tracks: it plays from there until you let go, then goes back; not while recording). fade work is an ordinary mouse gesture with the pointer. a tool acts on the clip you click, or on all the selected clips when that one is among them. the glue tool joins midi clips; for audio, use track > bounce in place ."],["editing-audio--select-a-range-across-tracks-and-edit-it","Select a range across tracks and edit it","Editing audio","editing-and-arranging.html","select a range across tracks and edit it choose the marquee tool (press t and pick it), then drag across one or more tracks; its edges snap to the grid (hold ctrl cmd , not to). dragging a range deselects any selected clips, so the commands below act on the range alone. its edges cut clips exactly (not at zero crossings). with a range: edit > delete , cut , copy and paste act on just that range. edit > delete and close gap , shift+backspace : remove it and move what's after earlier (the tracks' automation too; over every track, the markers, tempo, chords and lyrics as well). edit > insert silence : push everything from the range's start later by its length (see \"insert bars of silence\"). transport > set loop to selection , ctrl+u cmd+u : loop it. track > bounce in place ( ctrl+b control+b ): bounce just that range. file > export other formats > export range as wav... : what each track plays there, with its effects, one file per track. view > zoom > zoom to fit , z : fit it in view. drag inside it to move what's in it (clips cut at its edges, and its automation) to another place on the same tracks, snapped to the grid: what was where it lands is replaced, and the automation where it was holds the values either side. hold alt option to copy it instead (a razor edit). drag its right edge to stretch what's in it from its start: audio is time-stretched with its pitch kept (each clip's stretch mode; it stops following the tempo), midi notes spread out (or squeezed together), and the automation with them. longer, it covers what came after on those tracks; shorter (down to 50 ms), it leaves a gap. warped clips are left as they are. each is one undo step. click an empty lane to clear the range."],["editing-audio--delete-so-the-gap-closes-ripple-editing","Delete so the gap closes (ripple editing)","Editing audio","editing-and-arranging.html","delete so the gap closes (ripple editing) turn on edit > edit options > ripple edits : deleting (or cutting) clips moves the later clips on the track earlier to close the gap; their automation stays where it is. it's off whenever a song opens. or use edit > delete and close gap , shift+backspace , once, on selected clips or a marquee range (a range takes its automation along)."],["editing-audio--reverse-change-channels-or-export-a-clip","Reverse, change channels or export a clip","Editing audio","editing-and-arranging.html","reverse, change channels or export a clip right-click an audio clip: reverse plays it backwards. channels : stereo, mono (left + right), swap left and right, left only, right only. export as wav... saves the clip as heard (gain, fades, envelope, reversed or warped, its clip effects with their tail), without the track's effects, as a 24-bit wav in the song's exports folder; with several clips selected, a file each in a folder."],["editing-audio--remove-silence-between-phrases-strip-silence","Remove silence between phrases (Strip Silence)","Editing audio","editing-and-arranging.html","remove silence between phrases (strip silence) right-click an audio clip (a vocal, a tom track) > strip silence and choose quiet recordings (-50 db) , normal (-40 db) or loud or noisy (-30 db) : the quiet parts are cut out, leaving a clip for each phrase or hit. gaps shorter than a quarter of a second are kept, and each piece keeps a moment before the sound (10 ms) and after it (80 ms), so nothing is clipped off; there are no fades. the status line says how many clips are left; one undo puts them all back. clips that follow the tempo, play reversed or loop are skipped."],["editing-audio--make-audio-follow-the-song-s-tempo","Make audio follow the song's tempo","Editing audio","editing-and-arranging.html","make audio follow the song's tempo right-click an audio clip (a drum loop, say) > follow tempo : it stretches with the song's tempo and tempo changes, keeping its pitch, and stays locked to the beat. its own tempo is taken to be the song's where it starts; for a loop recorded at another tempo, right-click it > detect tempo... > clip follows song (see \"find the tempo of a recording\"). ordinary audio stays where it is in time when the tempo changes; midi always stays on its beats. right-click it > stretch mode for how it's stretched (following the tempo, warped or pitch shifted): standard (all-round, the default), percussive (the sharpest hits: drums, picked guitar) or smooth (bass, vocals, pads: softer attacks). all three stay on the beat; stretched a long way (half speed, say) hits soften and smear in any of them."],["editing-audio--tighten-the-timing-of-a-drum-take-warp-and-audio-quantise","Tighten the timing of a drum take (warp and audio quantise)","Editing audio","editing-and-arranging.html","tighten the timing of a drum take (warp and audio quantise) select audio clips and press q ( edit > quantise ), or right-click > quantise audio to grid : their hits move all the way to the snap grid (1/16 with the grid off), with its swing or groove; hits less than half a millisecond off stay. finding the hits can take a few seconds on a long clip. midi clips in the selection are left alone (quantise them in the midi editor). on clips in an edit group, q opens quantise group instead (below). for hand edits, right-click > warp (it also turns on follow tempo): click in the clip's top strip to put a marker on the nearest hit, drag to pin the audio there and move it; drag a marker to move it ( ctrl cmd , ignores the grid); alt option -click a marker to remove it. remove warp markers starts over."],["editing-audio--edit-a-multi-mic-drum-kit-as-one-edit-groups","Edit a multi-mic drum kit as one (edit groups)","Editing audio","editing-and-arranging.html","edit a multi-mic drum kit as one (edit groups) select the drum tracks (or their folder) and choose track > group > group for editing , ctrl+shift+g shift+cmd+g . their headers show g1 (g2 for the next group). now clicking a clip on one mic selects the clips at the same time on all of them, so a cut ( ctrl+t cmd+t ), move, nudge, delete or quantise does the same to the whole kit; trimming, fading or slipping one clip does the same to the others; a marquee range over one track covers the group; and comping a take on one mic (the takes lanes) comps the same take on the others. edit > edit groups on turns grouping off for a moment (to fix one mic on its own; the badges go faint); track > group > ungroup for editing ends it."],["editing-audio--tighten-a-multi-mic-drum-take-without-phase-problems-quantise-group","Tighten a multi-mic drum take without phase problems (Quantise Group)","Editing audio","editing-and-arranging.html","tighten a multi-mic drum take without phase problems (quantise group) quantising each drum mic on its own moves each by its own hits, so the overheads and rooms drift away from the close mics and the kit sounds smeared. with the kit grouped (above), select a clip on any mic and press q (or edit > quantise group... ); to do only a section, drag a marquee over it first. in the window: tick the tracks to find the hits on: the kick and snare are ticked to start with (the inside kick and top snare mics). move them by : cutting before each hit, crossfading the joins slices every mic 4 ms before each hit and moves the slices, with 6 ms crossfades: the hits stay exactly as played and the mics exactly in phase (the usual choice for drums). warping (stretching between the hits) stretches the audio between the hits instead: no joins, the mics within a millisecond of each other. strength (100%: all the way to the grid) and sensitivity (50% to start; higher finds ghost notes too), both remembered. hits within 30 ms of each other on different mics count as one. it uses the arrange view's grid and feel (swing, groove). one ctrl+z cmd+z puts it all back."],["editing-audio--jump-to-the-next-drum-hit-tab","Jump to the next drum hit (Tab)","Editing audio","editing-and-arranging.html","jump to the next drum hit (tab) transport > go to > go to next hit , tab, moves the playhead to the next hit (transient) on the selected tracks (or on the selected clips' tracks; with nothing selected, any track); shift+tab goes back to the one before. handy for cutting at hits ( ctrl+t cmd+t , splits there) and checking a quantise."],["editing-audio--slow-down-speed-up-or-transpose-a-clip","Slow down, speed up or transpose a clip","Editing audio","editing-and-arranging.html","slow down, speed up or transpose a clip right-click an audio clip: varispeed (tape: faster is higher) : 50, 67, 75, 80, 90, 95, 100, 105, 110, 125, 133, 150 or 200%, like a tape machine; length and pitch change together. the clip's start stays and its end moves (check it doesn't now run over the next clip), and it stops following the tempo. pitch shift (keeps the length) : -12 to +12 semitones, in the clip's stretch mode. both apply to every selected clip."],["editing-audio--correct-the-pitch-of-a-vocal","Correct the pitch of a vocal","Editing audio","editing-and-arranging.html","correct the pitch of a vocal double-click an audio clip (or right-click > pitch correction... ) to open the pitch editor under the tracks: sung notes as bars and the pitch as a line. tick correct : after a moment the corrected line sits on the notes of the key and the clip plays in tune, the voice still sounding like the singer. choose which notes are in tune ( song key , chromatic or notes i choose ), and set how far notes go ( correction , 100% to start), how quickly ( speed , 0 to 400 ms, 40 to start: 0 is the robotic effect, 100-200 ms keeps vibrato) and how much natural drift stays ( humanise , 30% to start). recorded clips open it; imported ones too. drag a note to send it to another note (hold alt option , to move it in cents); double-click one to leave it as sung. untick correct to hear the original."],["editing-audio--fix-single-notes-in-the-pitch-editor-split-join-vibrato-timing","Fix single notes in the Pitch editor (split, join, vibrato, timing)","Editing audio","editing-and-arranging.html","fix single notes in the pitch editor (split, join, vibrato, timing) right-click a note in the pitch editor: split the note here (a melisma or run found as one note, tuned to one pitch) or join with the next note (a legato note found as two). octave heard wrong : the note's real pitch is an octave above or below what's shown. vibrato (none, half, as sung, more, or as speed decides), drift (straightened, half, as sung, or as humanise decides) and tilt (a rise or fall through the note, a half or a whole semitone): for that note only, whatever speed and humanise say. formants (bigger or smaller voice, -3 to +3) and level (louder or quieter by 3 or 6 db). leave this note as sung , back to the nearest note in tune , reset this note . to move a note's timing, drag its start or end (the pointer shows arrows), or shift -drag the note to move it whole: it snaps to the grid (hold ctrl cmd , not to). that's written as warp markers on the clip, the audio half a second either side pinned so only the note and the gaps beside it stretch."],["editing-audio--tune-a-screamed-or-gritty-vocal","Tune a screamed or gritty vocal","Editing audio","editing-and-arranging.html","tune a screamed or gritty vocal in the pitch editor's more menu, pitch heard in says how readily pitch is heard: screams left alone hears pitch only in clean singing, so a scream or growl isn't touched (no warbling); clean voice , normal (the default), gritty or breathy voice and rough voice hear it in rougher and rougher singing. to leave one stretch alone (a scream, a spoken line), drag across it in an empty part of the editor and right-click > leave this stretch alone ( correct this stretch again undoes it). leave notes already in tune (flex-tune: off, 10, 20, 30 or 50 cents) leaves notes that close to a note in tune where they are, so only the ones that are off move."],["editing-audio--formants-the-chord-lane-breaths-and-levels-for-a-vocal","Formants, the chord lane, breaths and levels for a vocal","Editing audio","editing-and-arranging.html","formants, the chord lane, breaths and levels for a vocal in the pitch editor's more menu: formants (whole clip) : the whole clip's voice bigger (-) or smaller (+), -4 to +4, without changing its pitch (a double that sounds like another singer). follow the chord lane (chord snap) : each note goes to the nearest note of the chord playing there, not of the key (where the chord lane has chords). breaths and esses : the breaths turned down 6, 10 or 15 db (or breaths 10 db and esses 4 db), as dips in the clip's volume envelope (which you can then adjust). level the notes : quiet notes up and loud ones down, gently (half way) or fully (all to one level) , also in the envelope. correct the track's other clips the same way : a comp's clips with the same settings (not the note-by-note changes). show other tracks behind : the pitch of doubles and harmonies at the same time, faintly, to match them."],["editing-audio--write-lyrics-along-the-song-the-lyrics-lane","Write lyrics along the song (the lyrics lane)","Editing audio","editing-and-arranging.html","write lyrics along the song (the lyrics lane) view > lanes > lyrics lane shows a lane under the chords. click a line to select it (it lights up); shift -click another to select the lines between, ctrl cmd -click to add or take away one. drag to move the selected lines together (on the grid; hold ctrl cmd , to ignore it). ctrl+c cmd+c , ctrl+x cmd+x and delete copy, cut and delete the selected lines; ctrl+v cmd+v pastes them at the playhead, as far apart as they were (the words go on the system's clipboard too, to paste into a message). right-click for add a line here... , change , copy , cut , paste here , delete , paste lyrics from here... (a whole song's words, a line each, a bar apart, to drag into place after), clear all lyrics , lyrics window... and lyrics prompter . hyphens split a word into its syllables for the lead sheet (\"beau-ti-ful\"). double-click the lane (or view > lanes > lyrics lines... ) for the lyrics lines window: every line with where it's sung (bar|beat and the time), the one being sung lit. click a position or the words to type new ones: a position takes a bar (\"17\"), a bar and beat (\"17.3\") or a time (\"1:23.5\") and moves the line there; empty words take the line out. add line puts one where you double-clicked (or a bar after the selected line) with its words ready to type; delete takes the selected lines out; go to puts the playhead on the selected line; paste words... pastes a whole song's words from it. the rows selected there are the lane's selected lines too, so copy and paste work on them. while the song plays, the lane's header shows the first word of the line being sung. view > lanes > lyrics prompter shows the words big, for the singer: the line being sung, the next under it, and a bar across for how far through the line the song is. it opens by itself when recording starts if the song has lyrics; put it on a screen the singer can see. on the lead sheet (notation, and the printed and pdf parts) the lyrics go under the first part that isn't drums, a syllable a note."],["editing-audio--make-a-harmony-from-the-lead-vocal","Make a harmony from the lead vocal","Editing audio","editing-and-arranging.html","make a harmony from the lead vocal open the lead's clip in the pitch editor and choose more > make a harmony voice : a third, fifth or sixth above, or a third, fourth or octave below. the notes (as corrected) move that many notes of the key (or the chord, following the chord lane), keeping half the lead's own vibrato so it sounds like a second singer, onto a new track under the lead (\"lead harmony (3rd above)\"). undo takes it away."],["editing-audio--tighten-double-tracked-guitars-or-stacked-vocals-align-to-a-reference-take","Tighten double-tracked guitars or stacked vocals (align to a reference take)","Editing audio","editing-and-arranging.html","tighten double-tracked guitars or stacked vocals (align to a reference take) pick the take the others should follow (usually the tightest). select all the takes ( shift -click them), then right-click the reference > align selected to this clip > tight (100%) , natural (70%) (a little of each player's looseness kept) or loose (40%) . recorded or imported audio clips only. the hits (palm mutes, picked notes, consonants) of each other take are paired with the reference's nearest, within 80 ms, and moved onto them with warp markers; between hits the audio is stretched, with the percussive stretch mode so the attacks stay sharp. a hit with no partner nearby (a note only one take plays) is left where it is. move whole clips (no stretching) only slides each clip by their typical difference, for takes recorded together that are just a little apart. it takes a few seconds per take; one undo takes it all back, and the warp markers can be moved by hand afterwards (see warping above). the clip's name strip says \"warp\" once it's aligned."],["editing-audio--match-a-double-s-pitch-to-the-lead-vocal","Match a double's pitch to the lead vocal","Editing audio","editing-and-arranging.html","match a double's pitch to the lead vocal select the doubles (or gang vocals) and the lead, right-click the lead > match pitch of selected to this clip > tight, natural or loose. each double is pulled toward the lead's pitch moment by moment, wherever they're singing the same note (within two semitones, so a harmony is left alone), keeping its own formants, so it still sounds like a second voice. the double plays a new file in the song's audio folder (\"matched\" on its name strip); right-click it > remove pitch match puts its own audio back. do it after aligning the timing."],["editing-audio--take-out-a-squeak-a-click-hum-or-mouth-clicks-repair","Take out a squeak, a click, hum or mouth clicks (Repair)","Editing audio","editing-and-arranging.html","take out a squeak, a click, hum or mouth clicks (repair) right-click a recorded clip > repair : remove mouth clicks : lip smacks and tongue clicks on a close-miked vocal, found and smoothed over (the voice around them left alone). remove hum (50 hz: europe) / (60 hz: the americas) : mains hum and its harmonics, in narrow notches. spectral repair... : the clip's spectrogram (time across, pitch up, louder brighter). drag a box over the sound to take out (a chair squeak, a pick click, a cough stands out brighter), then remove selected : each frequency in the box comes down to what it is just before and after it, so what stood out goes and what was under it stays. each makes a new file the clip plays (undoable); take off repairs goes back to the original. the spectral window is titled \"spectral repair\" with the clip's name."],["editing-audio--move-the-playhead","Move the playhead","Editing audio","editing-and-arranging.html","move the playhead click anywhere in the lanes: on empty space, a clip, a folder, a section, a chord, a lyric or the tempo. the playhead goes there, snapped to the grid (hold ctrl cmd , for exactly where you clicked), and the click does what it does there too (a click on a clip still selects it). a click in the ruler puts it exactly where you clicked. clicks (in the ruler too) don't move it while recording. or only by dragging it: turn off settings > click in the tracks moves the playhead . then a click in the tracks selects and edits as usual and leaves the playhead where it is; to move it, drag the playhead's line in the tracks (the pointer becomes a two-way arrow over it), and it stays wherever you let go (on the grid; hold ctrl cmd , for exactly there). a click in the ruler still moves it. kept between launches. from the keys (in transport > go to , and go to start in transport ): - left / right, or , and . : back or on a bar. back from inside a bar goes to its start first. - shift+← / shift+→ : back or on a grid step (a beat with the grid off). - page up / page down: back or on by a screen (the width of the arrange view). - alt+, option+, / alt+. option+. : the start of the section before or the next one. - return or home : the start. end: the end of the song (where its last clip ends). - tab / shift+tab : the next or previous drum hit (see \"jump to the next drum hit (tab)\"). when the playhead moves out of view (from a key, go to start, or the assistant), the arrange view scrolls to show it. while playing, it pages along as the playhead reaches the edge. another key set ( settings > key commands... ) puts some of these on that set's keys (the sections, the end, the bars on the numpad)."],["editing-audio--follow-the-playhead-while-playing","Follow the playhead while playing","Editing audio","editing-and-arranging.html","follow the playhead while playing view > follow playhead , ctrl+shift+f cmd+shift+f , on to start with: while the song plays, the tracks page along when the playhead reaches the right edge. editing while it plays (moving or trimming a clip, dragging a marquee) or scrolling along the song yourself pauses it, so the view stays where you're working. it follows again on the next play or stop, or when you move the playhead (a click, a key). zooming doesn't pause it. turned off, the tracks stay where they are while playing."],["editing-audio--hear-the-audio-as-i-drag-the-playhead-scrub","Hear the audio as I drag the playhead (scrub)","Editing audio","editing-and-arranging.html","hear the audio as i drag the playhead (scrub) grab the playhead in the ruler (the pointer turns to a two-way arrow over it), or alt option -drag anywhere in the ruler, and drag: the audio under it plays in tiny loops as it moves, to find a hit, a word or a click by ear. let go and the playhead stays there (the song plays on if it was playing)."],["editing-audio--put-a-clip-at-an-exact-place-spot","Put a clip at an exact place (spot)","Editing audio","editing-and-arranging.html","put a clip at an exact place (spot) right-click a clip > spot... and type where it starts: a bar (17), a bar and beat (17.3), with ticks (17.3.480, 960 a beat), or a time (1:23.5, 83.5s, 0:01:23.5). with several clips selected, the earliest goes there and the others keep their places relative to it (midi clips too). one undo step. unlike a drag, it doesn't trim the clips it lands on: check for overlaps."],["editing-audio--zoom-and-scroll","Zoom and scroll","Editing audio","editing-and-arranging.html","zoom and scroll zoom: view > zoom > zoom in / zoom out , ctrl+= cmd+= / ctrl+- cmd+- or ctrl+→ cmd+→ / ctrl+← cmd+← , ctrl cmd -scroll, the scroll wheel over the ruler, or pinch on a trackpad (a windows touchpad's pinch works too). it zooms around the pointer, or around the playhead when the pointer is near it, so the playhead stays put. drag up or down in the ruler to zoom (down zooms in), moving sideways in the same drag to scroll. a drag sideways sets the loop range as before. double-click the ruler to zoom to fit, as z does (the range, the selected clips or the whole song; again to go back). scroll: the wheel scrolls through the tracks, shift -scroll scrolls sideways along the song, and a trackpad's two fingers scroll both ways at once. drag with the middle mouse button anywhere in the lanes to pan both ways. taller or shorter tracks: alt option -scroll or ctrl+shift cmd+shift -scroll, as well as view > zoom > taller tracks / shorter tracks . in the piano roll and the drum editor, the same makes the note rows taller or shorter, the row under the pointer staying where it is. view > zoom > zoom to fit , z : fit the marquee range, the selected clips or the whole song; press z again to go back. view > zoom > previous zoom , shift+z , goes back to how it was zoomed before, and again further back (each zoom is kept once it has settled, however many wheel or pinch moves made it); view > zoom > next zoom , alt+shift+z option+shift+z , goes on again. each song opens zoomed and scrolled as it was when it was last closed (kept in take 5's settings, not the song, so zooming never asks to save). the main window comes back at the size and place it was when take 5 was quit, full screen if it was."],["editing-audio--bring-in-audio-files","Bring in audio files","Editing audio","editing-and-arranging.html","bring in audio files drag audio (or midi) files from finder or explorer onto a track: a green ghost shows where it lands. a new track is named, coloured and given an icon from the file's name: \"kick_in_01.wav\" arrives as \"kick in\", red, with a drum (drums red, bass purple, guitars orange, keys green, vocals blue...); stems from another studio arrive looking like a session (a name that says nothing about an instrument stays as it is). aaf and other daws' sessions get the colours and icons, keeping their track names. track > colour tracks by instrument does it to the song's tracks now (keeping their names). several files: the first on that track, the rest on new tracks below; hold alt option to put them all on that track one after another. drop files between tracks, below the last one or into an empty song for new tracks there. file > import audio or midi... , ctrl+shift+i shift+cmd+i : asks whether to place them at the playhead or at bar 1, on new tracks (one each) or one after another on the selected track, and for midi files whether to keep the song's tempo or use the file's. view > panels > audio file browser , f : browse folders, click a file to hear it, drag files in. right-click a file > tags... to tag it (kick, punchy, room: kept for every song) and the places list then has tagged: kick ...; right-click > find similar sounds lists the sounds in the folder (and the folders in it) most like it, by how long, bright, sharp and noisy they are: a kick finds kicks, a hat finds hats, for drum replacement's samples. click one to hear it. files are copied into the song's audio folder."],["arranging--add-and-name-sections-intro-verse-chorus","Add and name sections (intro, verse, chorus)","Arranging","editing-and-arranging.html","add and name sections (intro, verse, chorus) sections show in the sections lane under the ruler ( view > lanes > sections lane , shift+g ). put the playhead where a section starts and choose track > add section marker , alt+' option+' : the marker goes at the nearest bar, named \"section 1\", \"section 2\"... or right-click the sections lane > add section marker here (on the grid where you clicked). a section runs to the next marker; the last one to the end of the song. with the playhead where a section already starts, the status line says so and nothing is added. double-click a section to rename it, or right-click > name for intro, verse, pre-chorus, chorus, bridge, solo, breakdown or outro ( rename... for your own name, add comment here... for a note at that point). drag a marker's left edge to move it (it snaps to the grid). to jump from section to section, use transport > go to > previous section / next section , alt+, option+, / alt+. option+. . each kind of section has a colour of its own (the usual names all differ: a bridge never looks like the chorus), and every one of a kind looks the same (\"chorus 2\", \"verse b\" and a \"refrain\" too)."],["arranging--loop-duplicate-or-delete-a-whole-section","Loop, duplicate or delete a whole section","Arranging","editing-and-arranging.html","loop, duplicate or delete a whole section right-click a section in the sections lane: loop this section sets the loop to it, turns looping on (and punch off) and puts the playhead at its start: for rehearsing or recording takes over just that part. duplicate section repeats it right after itself on every track (a second chorus). delete section (and everything in it) removes it and closes the gap. remove marker only keeps the music and removes the marker. the clips (cut at the section's edges), takes, automation on every track and the master, chords and lyrics go with the music: a duplicated section has its own copy of them, and after a deleted one they move up to close the gap. so do tempo and time-signature changes: a duplicated section starts at its own tempo and changes where it does, and after a deleted one the song goes on at the tempo that played after it. each is one undo step."],["arranging--try-the-song-in-another-order-arranger-chains","Try the song in another order (arranger chains)","Arranging","editing-and-arranging.html","try the song in another order (arranger chains) track > arranger chains opens a window with the song's sections (from its markers) as buttons: click them in the order you want them played, a section as often as you like (a chorus twice) and leaving out the ones you don't (the bridge cut). the chain shows as a list, each section with its bars and where it starts in the chain: move up , move down , remove and clear change it. play chain plays the song in that order without changing it (the song's playhead jumps along to where each section is in the song; the button turns to stop , and pressing play on the song stops the chain). new , duplicate , rename... and delete manage several chains to compare, and the drop-down switches between them; they're kept in the song, and each change is undoable. a section whose marker you delete drops out of the chains. export as wav... saves a chain's version as a file (in the song's exports, \"<song> - <chain>.wav\" to start with). flatten into song... (after asking) rewrites the song in the chain's order: every track's clips (cut at the sections' edges, with short fades there so the joins don't click), automation, markers, chords and lyrics. sections the chain leaves out are gone; one undo takes it all back. anything before the first marker is the section \"start\". a song that changes tempo or time signature can't use chains yet."],["arranging--insert-bars-of-silence","Insert bars of silence","Arranging","editing-and-arranging.html","insert bars of silence press t and choose marquee from the tool menu, drag a range as long as the gap you want, starting where the gap should go, and choose edit > insert silence : everything from the range's start moves later by its length, on the tracks the range covers, their automation too (the gap holds the value it had there); a clip across the start is split there. with nothing selected, the status line says how. over every track, it's the whole song that makes room: the section markers, tempo and time-signature changes, chords, lyrics and takes after it move too. over some tracks, only those tracks move. edit > delete and close gap , shift+backspace , does the opposite: it takes the range out and pulls what's after it back (over every track, the whole song's). one undo step each."],["arranging--set-the-tempo-and-time-signature","Set the tempo and time signature","Arranging","editing-and-arranging.html","set the tempo and time signature double-click the tempo in the transport bar's display and type a new one (20 to 400 bpm); pick a time signature from the box next to it (2/4, 3/4, 4/4, 5/4, 6/8, 7/8 or 12/8; the tempo lane has more). both change the tempo or signature the playhead is in: the whole song, for a song with no changes, or that stretch of it (to add a change, use the tempo lane). midi stays on its beats; ordinary audio stays where it is in time, so a recording no longer lines up with the bars (audio clips set to follow the tempo are stretched with it). the display always shows the tempo and signature at the playhead. each change is one undo step."],["arranging--tap-the-tempo","Tap the tempo","Arranging","editing-and-arranging.html","tap the tempo transport > tap tempo , shift+t : tap along at least twice and the tempo the playhead is in is set from your taps (the last eight, averaged). a pause of two seconds starts the count again. a run of taps is one undo step. the first tap only starts the count: the status line says to keep going. to set the tempo by typing, double-click the tempo in the transport bar. for a whole free-time take, see \"fit the tempo to a band take\"."],["arranging--add-tempo-changes-and-ramps-the-tempo-lane","Add tempo changes and ramps (the tempo lane)","Arranging","editing-and-arranging.html","add tempo changes and ramps (the tempo lane) view > lanes > tempo lane , g , shows the lane under the ruler. double-click (or right-click > add tempo change here ) to add a tempo change; it starts at the tempo already playing there. drag a point up or down for the tempo, in whole bpm (shift: tenths), or sideways to move it ( ctrl cmd , ignores the grid); a drag goes one way or the other, as it starts. a change can't be dragged past its neighbours, and the first one (the song's starting tempo) stays at the start. double-click a point, or right-click > set tempo... , to type a tempo; alt option -click it, or right-click > remove this change , to delete it. right-click a point > ramp to next for a smooth speed-up or slow-down to the next change. right-click or double-click the lane's top strip for a time signature from that bar (twelve to choose from), or to remove one."],["arranging--fit-the-tempo-to-a-band-take-played-without-a-click-conduct-tempo","Fit the tempo to a band take played without a click (Conduct Tempo)","Arranging","editing-and-arranging.html","fit the tempo to a band take played without a click (conduct tempo) choose transport > conduct tempo (choose it again to stop without making anything). play the take from the start and tap shift+t on every beat (or every half bar, or bar), the first tap on a downbeat. stop: say what each tap was (\"each tap was a beat\", half a bar or a bar), then make the tempo ( keep tapping to go on, discard to throw the taps away). it needs two taps or more. the bar lines now fall on the played downbeats, the tempo lane shows the speeding up and slowing down, and the audio hasn't moved, so the click and midi follow the band. the taps are corrected for the interface's delay, and the bars are in the song's starting time signature. one ctrl+z cmd+z undoes it."],["arranging--find-the-tempo-of-a-recording","Find the tempo of a recording","Arranging","editing-and-arranging.html","find the tempo of a recording right-click an audio clip > detect tempo... : for a loop or a take played to a steady beat (six seconds or more), it suggests a tempo between 60 and 200 bpm, to a tenth of a beat per minute (or says none was found). it hears the beat from where the notes start, and the bar from how they repeat, so strummed eighths don't come out twice as fast; between two that fit equally well it picks the more usual tempo (a song at 70 could come out as 140). choose set song tempo to set the song's starting tempo to it, or clip follows song to stretch the clip to the song's tempo instead. for a band take played without a click, see \"fit the tempo to a band take\"."],["arranging--make-linked-copies-of-a-midi-part-or-an-audio-clip","Make linked copies of a MIDI part or an audio clip","Arranging","editing-and-arranging.html","make linked copies of a midi part or an audio clip select a clip (midi or audio) and choose edit > repeat linked , ctrl+alt+r option+cmd+r , or right-click it > repeat linked : a copy right after it, linked (shown by a link before its name). midi: editing the notes of any copy changes them all. audio (the chorus guitar used three times): a fade, gain, pan, reverse, pitch, warp marker, envelope or clip effect on one is on all of them. each keeps its own place, length, trim, name, colour and mute. right-click one > unlink (it says how many others it's linked to) to vary it on its own. plain repeat , ctrl+r cmd+r , makes an independent copy."],["midi-and-instruments--add-an-instrument-track","Add an instrument track","MIDI and instruments","writing-and-midi.html","add an instrument track track > new instrument track... , ctrl+alt+s option+cmd+s , opens a menu: synth (built in) : a track named \"synth\". drum machine (built in) with a kit: vintage kit (the usual), club kit, rock kit, or the synthesised electronic kit; a track named \"drums\". keys (built in) : grand piano, soft grand piano, upright piano, electric grand, pianet, wurlitzer, drawbar organ. bass (built in) : jazz bass, picked bass, upright bass, electric bass. guitar (built in) : steel-string, nylon and clean electric guitar. strings and pads (built in) : tremolo strings, sweep pad, choir pad. sampler (built in)... : your own sample or .sfz instrument. plugins : your scanned instrument plugins, by maker (none until you scan: settings > plugins... ). the new track is selected, ready to arm and play; one undo step. dropping an .sfz file onto the song also makes an instrument track that plays it."],["midi-and-instruments--write-notes-in-the-piano-roll","Write notes in the piano roll","MIDI and instruments","writing-and-midi.html","write notes in the piano roll double-click an instrument track's lane to make a midi clip; the midi editor opens below (also view > midi editor , p , or double-click any midi clip). in the piano roll: click the empty grid to add a note (a grid step long, velocity 100, inside the clip); drag a note to move it (all selected ones); drag its end to resize it (down to a quarter of a grid step). hold ctrl cmd to add, move or resize off the grid. shift -click adds a note to the selection or takes it out; drag the empty grid to select several ( shift -drag adds them). backspace or delete removes the selected notes; ctrl+a cmd+a in the editor selects every note. drag the bars in the velocity lane to change velocities (1 to 127): dragging a selected note's bar changes all the selected ones by the same amount. one undo step a drag. click a key on the keyboard to hear it (louder further right); slide along the keys to play each. alt option -scroll makes the rows taller or shorter. piano roll / drums / notation switch the view; key , transform , step input and quantise are next to them."],["midi-and-instruments--quantise-notes","Quantise notes","MIDI and instruments","writing-and-midi.html","quantise notes press q ( edit > quantise ) to snap the selected notes (or all of them) to the snap grid, with its feel (straight or swung, from the feel box). for more control, click quantise in the midi editor: outlines show where notes will go before you apply it. strength (100% to start) moves them part of the way, a narrower window (100% to start) moves only notes near the grid, note ends too squares off lengths; align sets a gentle pass (60%, notes near the grid, ends left alone) for you to apply with quantise (it closes). midi > align notes applies that gentle pass at once. each is one undo step. q always goes all the way to the grid; the panel's settings (kept while take 5 is open) are used when you press its own quantise . with audio clips selected, q quantises the audio instead (see \"tighten the timing of a drum take\"); on a drum kit in an edit group, it opens quantise group."],["midi-and-instruments--quantise-to-the-feel-of-another-part-groove","Quantise to the feel of another part (groove)","MIDI and instruments","writing-and-midi.html","quantise to the feel of another part (groove) right-click a midi clip you played (a drummer's hi-hats, say) > use as groove , or a recorded drum take (audio) > use as groove (its feel) : its hits are found and how far each sits from the grid (set in the snap box) is the feel. the feel box then shows \"groove: <clip>\", and quantising midi parts makes them take on that feel, so a programmed bass or synth part sits with the real drummer. the groove applies while the snap box is on the grid it was taken with (on another grid quantising is straight, until you go back to that one), and it's kept with the song. choose straight (or a swing) in the feel box to go back."],["midi-and-instruments--play-notes-from-the-computer-keyboard-musical-typing","Play notes from the computer keyboard (Musical Typing)","MIDI and instruments","writing-and-midi.html","play notes from the computer keyboard (musical typing) midi > musical typing , ctrl+k cmd+k , opens a window with the keys. with an instrument track armed, a s d f... play the white keys (a is middle c to start) and w e t y... the black keys; z / x go an octave down / up, c / v change the velocity (by 20; 100 to start), tab is the sustain pedal; the window shows the octave and velocity. it plays as a midi keyboard would, so the armed instrument track hears it. record with it like a keyboard. while it's open, letters play notes instead of running shortcuts (typing in a text box still types). keys the instrument can't reach are dimmed, and the window says which way to go (for example \"z for lower\"). ctrl+k cmd+k again closes it."],["midi-and-instruments--enter-notes-one-step-at-a-time-step-input","Enter notes one step at a time (step input)","MIDI and instruments","writing-and-midi.html","enter notes one step at a time (step input) open a midi clip in the editor and choose midi > step input , alt+i option+i , or its button in the editor. play notes or chords on your midi keyboard: each goes in at the playhead (on the grid; at the clip's start if the playhead isn't in it), as loud as you played it, and it moves on a step. set the step length in the box that appears (1/1, 1/2, 1/4, 1/8, 1/16, 1/32, 1/8 t or 1/16 t; the snap grid to start); rest leaves a gap, tie makes the last notes a step longer, back takes the last step out. the clip grows if you write past its end. each step is one undo step."],["midi-and-instruments--mute-notes-without-deleting-them","Mute notes without deleting them","MIDI and instruments","writing-and-midi.html","mute notes without deleting them select notes in the piano roll and choose midi > mute notes ( ctrl+m control+m ; a real control key, not the command key): they're drawn faded and don't play, export or show in notation. with none selected it mutes the whole clip. the same key unmutes them (if all are muted already). useful for trying a part without some notes, or keeping a wrong note to fix later. it needs the midi editor open ( p ); it's in transform too."],["midi-and-instruments--humanise-transpose-and-change-velocities-transform-notes","Humanise, transpose and change velocities (Transform Notes)","MIDI and instruments","writing-and-midi.html","humanise, transpose and change velocities (transform notes) the midi editor's transform button (or midi > transform notes ) works on the selected notes, or on every note in the clip (the menu's first line says which): humanise... : small nudges in timing (up to 12 ms) and velocity (up to 10 either way). legato : each note runs to the next one's start (notes starting together count as a chord). remove doubled notes : the same key twice within 40 ms (a keyboard's double triggers). fixed length : 1/1 to 1/32. scale velocities... (a percentage and an amount), compress velocities... (50% evens them out half way, 100% makes them all the same, below 0 spreads them) and set velocity... (1 to 127). transpose... (semitones, 12 to start), transpose in key (up or down a step, a third, a fifth or an octave, in the song's key) and snap to key (each note to the nearest one in the key). each is one undo step."],["midi-and-instruments--set-the-song-s-key-and-see-notes-outside-it","Set the song's key and see notes outside it","MIDI and instruments","writing-and-midi.html","set the song's key and see notes outside it click the key button in the midi editor (\"key: c major\") or midi > song key : choose the key and scale (major, minor, dorian, phrygian, lydian, mixolydian, locrian, harmonic minor or melodic minor), or detect key from this clip on a played part (it says when there aren't enough notes to tell). a new song is in c major; the key is kept with the song, each change one undo step. with shade notes outside the key on (it is to start with), out-of-key rows are shaded in the piano roll and the root is tinted. the key is also used for notation spelling, chord ideas, transpose in key and pitch correction."],["midi-and-instruments--draw-pitch-bend-mod-wheel-and-other-controllers","Draw pitch bend, mod wheel and other controllers","MIDI and instruments","writing-and-midi.html","draw pitch bend, mod wheel and other controllers in the midi editor, choose what the bottom lane shows: velocity, pitch bend, mod wheel (cc 1), expression (cc 11), volume (cc 7), pan (cc 10), sustain (cc 64), breath (cc 2), brightness (cc 74), aftertouch, any other controller the clip already uses (marked), or other cc... (any number, 0 to 127). drag to draw freehand, shift -drag for a straight line, alt option -drag to erase; each stroke is one undo step. each value holds until the next; pitch bend snaps to the middle near it. the instrument follows it on playback."],["midi-and-instruments--add-an-arpeggiator-or-chord-effect","Add an arpeggiator or chord effect","MIDI and instruments","writing-and-midi.html","add an arpeggiator or chord effect select an instrument track and choose midi > add midi effect (greyed until one is selected): arpeggiator : pattern (up, down, up & down, as played, random; up to start), rate (1/4 to 1/32, with triplets; 1/16 to start), octaves (1 to 4) and gate (how long each note is, 5 to 100%; 80 to start). hold a chord and it plays its notes in turn, in time with the song. chord : one key plays a chord of that shape on any key: major, minor, 7th, major 7th, minor 7th, sus 4, sus 2, power (5th) or octaves (not tied to the song's key). transpose (midi modifier) . it goes before the track's instrument (after any other midi effect) and its window opens. one undo step."],["midi-and-instruments--map-a-controller-knob-to-a-fader-or-plugin-midi-learn","Map a controller knob to a fader or plugin (MIDI learn)","MIDI and instruments","writing-and-midi.html","map a controller knob to a fader or plugin (midi learn) right-click a fader, pan knob or a slider in a built-in plugin's window > midi learn... , or choose midi > midi learn and pick the selected track's volume, pan or a plugin parameter. then move a knob or fader on your controller: they're linked (controllers only: notes and pitch bend aren't learnt; one knob for one control). esc cancels while it's waiting; right-click > forget unlinks one. a third-party plugin's own window can't be learnt from (use the built-in sliders, or midi > midi learn ). midi > midi mappings... lists the mappings and removes them; they're saved with the song."],["midi-and-instruments--import-or-export-a-midi-file","Import or export a MIDI file","MIDI and instruments","writing-and-midi.html","import or export a midi file import: drag a .mid file into the song (new tracks where you drop it, on the song's tempo), or file > import audio or midi... . each part gets a track (channel 10's drums on a drum machine, the rest on the built-in synth), with its controllers and pitch bend. the import window asks where (at the playhead or bar 1), whether onto new tracks or merged into the selected instrument track, and the tempo: keep the song's tempo (to start with) or use the midi file's tempo and time signature . export: file > export other formats > export midi file... writes the whole song (tempo, time signatures, key, section markers, a track per part, drums as drums). right-click a track > export track as midi file... , or a midi clip > export as midi file... , for just that."],["midi-and-instruments--write-chords-in-the-chord-lane","Write chords in the chord lane","MIDI and instruments","writing-and-midi.html","write chords in the chord lane view > lanes > chord lane shows the song's chords under the sections. double-click to add a chord (type a name like c, am7, f#dim, bbmaj7, dsus4), drag a chord to move it, right-click to change or remove it ( change... , remove ); chords snap to the grid. a name it doesn't know says what it does know (\"try c, cm, c7...\"). from a midi clip of chords: select it, right-click the lane > chords > detect chords from clip (a chord a bar) or (a chord a beat) . to hear them, chords > make a clip from the chords : held chords , bass note and chord or arpeggio (eighths) , on the selected instrument track (or a new \"chords\" track), over the marquee or the whole chord lane. remove all chords clears it. the same chords menu is in midi > chords . the chords print above the notation."],["midi-and-instruments--get-chord-progression-and-melody-ideas","Get chord progression and melody ideas","MIDI and instruments","writing-and-midi.html","get chord progression and melody ideas put the playhead in a section (or drag a marquee over the bars; with neither, the 8 bars from the playhead), show the chord lane, right-click it > chords > chord ideas for ... and choose a style (pop, ballad, rock, folk, jazz), a chord a bar or two a bar: chords in the song's key replace the ones there, and choosing again gives another idea. then chords > melody idea for ... and a contour ( arch (up, then down) , rising , falling , wave ) and density (sparse, medium, busy): a \"melody idea\" clip on the selected instrument track, or a new \"melody\" track on the built-in synth. keep it, edit it like any midi, or delete it. ctrl+z cmd+z undoes either."],["midi-and-instruments--strum-chords-add-flams-and-grace-notes-chop-and-ratchet-notes-writing-parts-faster","Strum chords, add flams and grace notes, chop and ratchet notes (writing parts faster)","MIDI and instruments","writing-and-midi.html","strum chords, add flams and grace notes, chop and ratchet notes (writing parts faster) in the midi editor, midi > transform notes (or the editor's own menu) works on the selected notes, or every note in the clip when none are: strum chords : each chord's notes one after another like a guitar: down (low to high) , up (high to low) , or down and up, alternating chord by chord; each later string a little softer (18 ms apart, each string 4 softer). strum spread... strums down with your own spacing (1 to 200 ms) and softening. add flams : a softer hit (60%) of the same note 25 ms before each (snares). add grace notes : a short note (a 32nd) a semitone or a tone below (or a tone above) leading into each. chop into repeats : each note cut into 2, 3, 4 or 8 equal repeats. ratchets : each note played 2, 3, 4 or 6 times in its length, short, or dying away (to 40%). chance (plays some of the time) : a note plays 75 %, 50 % or 25 % of the time, the dice rolled again each time round (a hi-hat that varies, a ghost note now and then). always puts it back. a note with a chance is drawn dashed, with its percentage on it. euclidean rhythm... : hits spread as evenly as they go over a number of steps (3 of 8 is the tresillo, 5 of 16 a son clave's feel), turned by a rotation, at a note you name (c1, f#1 or a number), over the whole clip, replacing that note's hits there (3 of 8 eighths on c1 to start; up to 64 steps). random rhythm... does the same from a seed and a density (16 sixteenths, 50%, f#1 to start): the same seed gives the same rhythm, another seed another one. both fill the whole clip, whatever's selected. each is one undo step."],["midi-and-instruments--turn-a-sung-or-hummed-melody-into-midi-melody-to-midi","Turn a sung or hummed melody into MIDI (Melody to MIDI)","MIDI and instruments","writing-and-midi.html","turn a sung or hummed melody into midi (melody to midi) right-click an audio clip of one voice or instrument (a vocal, a hummed idea, a bass di, a lead guitar) > melody to midi : its notes, found as the pitch editor finds them (its splits, joins and octave fixes included), become a midi clip on a new instrument track under it, each note rounded to the nearest semitone and as loud as it was sung, on a track named \"<track> notes\" (if no notes are found, the status line says so). it plays on the built-in synth (change the instrument as for any track); the notation view shows it as notes, and as tab on a guitar or bass part. short blips (under 70 ms) are left out. the other way, correct to a midi part (same menu) corrects the clip's pitch to a midi part on a track you choose (tracks with midi clips): each sung note goes to the midi note playing at its middle (as if each were set by hand in the pitch editor, where they show and can be changed). one undo step each."],["midi-and-instruments--show-a-part-as-sheet-music-notation","Show a part as sheet music (notation)","MIDI and instruments","writing-and-midi.html","show a part as sheet music (notation) open a midi clip and click notation in the midi editor ( midi > notation , ctrl+shift+n shift+cmd+n ). notes show in the song's key and time signature with the chord lane's chords above; whole track shows every clip on the track; the box next to it rounds played timing to 1/8 , to 1/16 (to start) or to 1/32 (kept with the song, and the same as sheet music's). click a note to select it ( shift -click for more, esc for none), drag it up or down or press up/down to move it a semitone ( ctrl cmd : an octave), 2 to 7 set its length (2 a 32nd, 3 a 16th, 4 an eighth, 5 a quarter, 6 a half, 7 a whole note), . dots it, delete removes it, left/right go to the next note. each edit is one undo step. the notes playing light up and the page follows the playhead."],["midi-and-instruments--show-guitar-or-bass-tab","Show guitar or bass tab","MIDI and instruments","writing-and-midi.html","show guitar or bass tab a midi track with a word like \"gtr\", \"guitar\" or \"bass\" in its name gets tab by itself ( automatic (from the name) ; drum tracks never do). or right-click the track > notation > guitar with tab or bass with tab ( standard for none), and pick a tuning there: for guitar standard, half or whole step down, drop d, c#, c or b, dadgad, open d, e, g or c, and 7- and 8-string tunings; for bass standard, half step down, drop d, bead, 5-string (low b or high c) and 6-string. guitar is written in treble clef an octave down with tab below; bass in bass clef with a line per string. click a fret number to select its note."],["midi-and-instruments--print-sheet-music-or-save-it-as-pdf-or-musicxml","Print sheet music or save it as PDF or MusicXML","MIDI and instruments","writing-and-midi.html","print sheet music or save it as pdf or musicxml file > export other formats > sheet music... , ctrl+p cmd+p , or the midi editor's sheet music... button. tick the parts (the midi editor's part, or the selected tracks, or all, to start with), set the title, paper (a4 or us letter), shortest note (eighth, sixteenth or 32nd notes), triplets, chord symbols and section names (kept with the song), and check the preview, page by page. print... prints (on windows it opens the pdf in your pdf viewer to print from), save pdf... saves it, save parts... saves each ticked part as its own pdf for each player, and save musicxml... writes a file for notation apps (musicxml is the format they share). one part with chords makes a lead sheet. the midi itself isn't changed."],["midi-and-instruments--use-the-sampler-with-my-own-samples","Use the Sampler with my own samples","MIDI and instruments","writing-and-midi.html","use the sampler with my own samples track > new instrument track... > sampler (built in)... and pick a wav, aiff, flac or ogg sample (played across the keyboard; its root note is the one written in the file, or a note name in the file name like \"piano c4.wav\", or c4; its loop is used) or an .sfz instrument (with its zones, velocity layers and loops). the sampler's window has attack , decay , sustain , release , cutoff , resonance , volume and velocity (how much playing harder is louder), and can load another sample. the sustain pedal works."],["drums--program-a-beat-on-the-drum-machine","Program a beat on the Drum Machine","Drums","writing-and-midi.html","program a beat on the drum machine track > new instrument track... > drum machine (built in) and a kit: vintage kit (the usual), club kit, rock kit or electronic kit (synthesised). in its window (click its plugin slot): the pads : 16, the kick at the bottom left, then the snares, hats, toms and cymbals going up. click one to hear it, harder lower down on the pad. the step grid edits the drum track's midi clip at the playhead (or its first clip), a page of 16 sixteenths at a time (a bar in 4/4): click a step to add or remove a hit, shift -click an empty step for an accented one. the line above says which clip and bar it is (\"pattern: drums, bar 1 of 16 (song bar 3)\"); < and > go to its other bars (the grid follows the playhead again when you play). new 1-bar pattern here makes a clip a bar long where the playhead is (on a drum track with no clip yet, make a 1-bar pattern ). one undo step. the drum editor shows the same notes with the pads' names (see \"edit drums in the drum editor\")."],["drums--change-a-drum-pad-s-sound-or-kit","Change a drum pad's sound or kit","Drums","writing-and-midi.html","change a drum pad's sound or kit in the drum machine window: kit switches the whole kit (vintage, club, rock or electronic), even while it plays. it replaces every pad's sound and settings (your own samples too); each pad keeps its output. select a pad (\"pad 1: kick\") to change its tune (-24 to +24 semitones), decay (natural, or cut off after up to 3 seconds), pan and level (-24 to +12 db). on the recorded kits a pad has several samples (soft to hard, and alternating), and these change them all together. drop a sample (wav, aiff, flac, ogg or mp3) on a pad to replace its sound, or right-click it > load sample... , choke group (none or 1 to 4: pads in a group cut each other off, as the open and closed hi-hat do; the hats start in group 1, shown on the pads) or remove sample . the kit and the pads are kept with the song. undo puts each change back (a slider drag is one step)."],["drums--edit-drums-in-the-drum-editor","Edit drums in the drum editor","Drums","writing-and-midi.html","edit drums in the drum editor open a drum track's midi clip (double-click it, or p): the editor shows a row per drum, named, with hits as diamonds coloured by family (kicks red, snares orange, hats yellow, toms teal, cymbals violet). on a track that isn't a drum machine, click drums in the midi editor for the standard drum names (any note the kit doesn't name still gets a row, by its note). add, move and delete hits and change velocities (the lane at the bottom) as in the piano roll; q quantises. hits snap to the grid (hold ctrl cmd , for off-grid), have no length to change, and clicking beside a hit that's already in that grid cell selects it rather than adding a second one (the piano roll does the same for notes). the editor opens in piano roll or drums from the clip's track each time. view > windows > midi editor in own window floats it."],["drums--give-the-kick-snare-and-hats-their-own-mixer-channels","Give the kick, snare and hats their own mixer channels","Drums","writing-and-midi.html","give the kick, snare and hats their own mixer channels right-click the drum track's header > drum channels > kick, snare, hats, toms and cymbals (or every pad ): tracks appear under it, one per group, each with its own fader, plugins and sends. put a compressor on the kick without touching the hats. the groups: the snare with the side stick and clap; the closed, pedal and open hats; the four toms; the crash, ride and ride bell. the tambourine and cowbell stay on the drum track, and only pads that have a sound get a channel (up to 16). in the drum machine window, a pad's output moves it: drum track (main) , a channel, or new channel for this pad . soloing a channel plays just it; muting the drum track leaves its channels playing. drum channels > all back to one output undoes it; deleting a channel puts its drums back on the drum track. each is one undo step, kept with the song. a drum track with channels can't be frozen (nor a channel on its own), and a channel bounces whole, not a range of it."],["drums--slice-a-drum-loop-onto-pads","Slice a drum loop onto pads","Drums","writing-and-midi.html","slice a drum loop onto pads import a drum loop, right-click it > slice at hits > under onto drum machine pads (up to 16) , choose fewer slices (the main hits) , normal or more slices (quieter hits too) . a new track below, \"<clip> slices\", gets a drum machine with a slice on each pad (slice 1, slice 2...) and a midi clip that plays the loop as it was; the original is muted. with more than 16 hits the strongest are kept, the weaker ones joining the slice before. the slices are taken as the clip plays (its gain, fades, reverse or warp) and saved as wav files in the song's audio folder. move or quantise hits in the drum editor to rearrange it. across sampler keys puts a slice on each key from c1 instead (up to 92; good for riffs and vocal phrases). one undo step."],["drums--add-a-sample-to-every-kick-or-snare-hit-drum-replacement","Add a sample to every kick or snare hit (drum replacement)","Drums","writing-and-midi.html","add a sample to every kick or snare hit (drum replacement) right-click the kick (or snare) mic's audio track header > drum replacement... . with a marquee range on the track, only that range is used. the picture shows every hit found at its level (\"520 hits in 180 s, 40 quieter ones left out\"). adjust sensitivity (higher finds quieter hits; 50% to start), gap (5 to 150 ms, 30 to start: lower for fast double kick) and leave out quieter than (-60 to 0 db, or drag the line) so only real hits count, not bleed. each hit's level is measured in its own drum's band (a kick's lows, a snare's crack), where another drum's bleed is far quieter, so the -24 db it starts at leaves most bleed out and keeps ghost notes. choose the drum (guessed from the track's name: \"kick in\" picks the kick) and kit, or sample of your own... (wav, aiff or flac), and blend under it or replace it (which mutes the original and sets the level to 0 db; blended, it starts at -6). line up with it (time and polarity) is on to start with; off, flip polarity and nudge (up to 10 ms either way) are yours to set. make trigger : a \"<track> trigger\" track appears right under it, lined up in time and polarity, each hit as loud as the one it's under. solo the trigger to check every hit. its track menu > drum replacement settings... changes it later ( update trigger finds the hits again: edits you made to the trigger's notes are lost). one undo step takes it all back."],["drums--a-drum-part-for-the-song-before-the-drummer-s-heard-it-the-session-drummer","A drum part for the song before the drummer's heard it (the session drummer)","Drums","writing-and-midi.html","a drum part for the song before the drummer's heard it (the session drummer) track > new drummer track adds a drummer: a track called \"drummer\" at the end, a drum machine (with the rock kit) that plays a part for the whole song, following its sections (add section markers first, track > add section marker; with none it plays the whole song). its window opens; press play. track > drummer... (or the track header's menu > drummer... ) opens it again, for the selected drummer track or the first. it sets how it plays: style : rock, half-time, punk, metal (double kick) or blast beat. a section can have its own ( drummer's style follows the drummer's). kick follows : a track whose rhythm the kick plays (its midi notes, or the hits in its audio), e.g. the bass; nothing (the groove's kick) to start with. for each section: plays (off for a break), simple - busy (which groove and fill), soft - loud (how hard; from three-quarters up the hats move to the ride, in a blast beat to the crash) and fill into it ( none , short : the last two beats, or long : the whole bar before it). double-click a slider for the middle. sections start from their names: an intro softer and simpler, a verse a little quieter, a chorus or solo louder and busier with a long fill into it, an outro loud, a break silent. every change writes its part again (a midi clip per section) as one undo step; the same settings always give the same part. write again catches up after the song's sections, tempo or the followed track change. turn into midi keeps the part as ordinary clips with every hit, to edit in the drum editor; if you edit the drummer's clips without doing that, it asks before writing over them (\"write the drummer's part again?\"). other clips you put on the track are left alone. the settings are kept with the song, by section (renaming a section keeps its settings). a drum machine track with nothing on it yet: its track menu > make it the drummer . bars not in 4/4 get a plain beat for now. the assistant can do all of it (\"a punk drummer, busy in the choruses, the kick on the bass\")."],["mixing--open-the-mixer","Open the mixer","Mixing","mixing.html","open the mixer view > mixer , x , shows or hides the mixer; so does the × at the right of its title bar. where it shows is up to you: view > windows > mixer in place of tracks (to start with), mixer below tracks (drag the edge between them to resize) or mixer in own window ; it's remembered with the layout. with the mixer in place of the tracks, the window's close button closes the mixer first (the status bar says so); click it again to quit. the strips are laid out as on a console: the track's name at the top, then its inserts (plugin slots) and sends , then pan and stereo width, the fader with its db scale and meter, ø (polarity), the level, arm, mute and solo, and the name again at the bottom. the fader stays a sensible height, so a taller mixer shows more slots rather than a longer fader; a short one (below the tracks) drops the headings and the fader shrinks to fit the slots; sends that don't fit are in the track's menu, the inspector and the headers. click a strip's name to select its track, drag it to move the track (into or out of a folder too). a vca's strip has just its fader, name, mute and solo; a bus has no arm button. the master strip is on the right with talk , listen , mono , dim (20 db down), master off and mix / ref ; mono and dim change only what you hear, never an export. in the console layout the strips also have routing and pre (see \"work in the console layout\")."],["mixing--see-a-track-s-settings-in-the-inspector","See a track's settings in the Inspector","Mixing","mixing.html","see a track's settings in the inspector view > inspector , i , shows a column at the left of the tracks (and of the mixer, when it's in their place) for the selected track. click a track or a clip and it follows; with nothing selected it keeps the last track. click a section's heading to fold it away (take 5 remembers which); drag its right edge to make it wider (double-click the edge for the default width); the x in its title bar, or i again, closes it. clip (when a clip is selected): its name , start , end and length ; for audio clips its gain (-24 to +24 db; double-click for 0), fade in and fade out ; muted . click a value to type a new one: start takes a bar (\"17\"), a bar and beat (\"17.3\") or a time (\"1:23.5\") and moves the clip there; end trims the clip's end; fades take milliseconds (\"250\") or seconds (\"1.5 s\"). several clips selected: the first is shown. track : its name, colour (click for the palette), input (audio inputs, or midi inputs for an instrument track, or no input ), output (the master or an output of the interface; a bus has neither) and notes . channel : the track's mixer strip, with its inserts, sends, pan, fader and buttons, and beside it the strip of where it goes (its folder, when the folder is a submix, or the master; none when it goes straight to an interface output). every change is one undo step (but notes, which are kept as you type)."],["mixing--set-levels-pan-and-width","Set levels, pan and width","Mixing","mixing.html","set levels, pan and width drag a fader or pan knob; double-click it, or alt option -click it, to go back to 0 db or centre. shift -drag moves it in fine steps, a tenth as far (pressing shift partway through a drag works too). ctrl cmd -click any fader or knob to type an exact value (\"-6\", \"-inf\", \"l30\", \"c\", \"120%\"). these work on every knob and fader in take 5. the width knob next to pan (0 to 200%): fully left (0%) is mono, the middle (100%) leaves it as it is, fully right is twice as wide. undo puts fader, pan and send moves back, one step per drag. the mouse wheel over a track header's fader or pan scrolls the tracks rather than moving them, so scrolling never changes a level by accident."],["mixing--solo-and-mute-tracks","Solo and mute tracks","Mixing","mixing.html","solo and mute tracks m mutes, s solos. a soloed track keeps its reverb and delay buses. alt option -click an s: solo just this one. shift -click an s: dry solo, without the buses it sends to (the s shows d). right-click an s for those ( solo , solo just this one , dry solo, without its buses ), solo-safe (never silenced by another solo) (for a reverb bus; its s stays half lit), unsolo all and unmute all . mix > unsolo all and unmute all do the same. soloing a folder keeps the buses its tracks send to. solos are kept in the song but aren't undo steps (press the s again)."],["mixing--add-a-reverb-or-delay-on-a-bus-sends","Add a reverb or delay on a bus (sends)","Mixing","mixing.html","add a reverb or delay on a bus (sends) track > other new tracks > new bus adds a bus (\"bus 1\"...); put a reverb or delay on it. then right-click a track > send to and pick the bus (or new bus... ; a bus already sent to is ticked, and picking it again removes the send), or use the + send button on its mixer strip. a new send starts at -10 db, with a level knob of its own. right-click a send's name > pre-fader (the fader doesn't change it) to make it independent of the track's fader (it shows \"(pre)\"), or remove send . each is one undo step. on the bus the effect should be all effect, no dry sound (the track's own dry sound is already in the mix): a built-in reverb or delay added to a bus starts that way (reverb's dry level all the way down, delay's mix at 100%), and convolution reverb starts fully wet anywhere. a third-party reverb on a bus: turn its mix fully wet."],["mixing--real-sounding-rooms-halls-and-plates-convolution-reverb","Real-sounding rooms, halls and plates (Convolution Reverb)","Mixing","mixing.html","real-sounding rooms, halls and plates (convolution reverb) add built-in > convolution reverb (on a bus, as above; it starts fully wet). space picks the room: small room, studio room (to start with), drum room, chamber, plate, short plate, concert hall or cathedral (or your own: own ir ). each is made from a room's size and shape (its early reflections) and how long it rings in the lows, mids and highs, and they're all levelled alike, so switching spaces changes the sound, not the volume. pre-delay (0 to 250 ms, 10 to start) holds the reverb back after the sound (clearer vocals), length (10 to 100%) shortens it with a smooth fade, low cut (20 hz to 1 khz, 80 to start) and high cut (1 to 20 khz, 12 to start) keep it out of the bass and take the fizz off, width (0 to 150%) narrows or widens it, mix sets wet against dry (lower it when it's on a track itself). load ir... uses an impulse response of your own (wav or aiff): a recording of a real room, hall, plate or spring (free ones are online; check each one's licence). it adds no latency, so it can be on a track you're recording through."],["mixing--make-a-knob-move-by-itself-modulators-lfo-envelope-follower-steps","Make a knob move by itself (modulators: LFO, envelope follower, steps...)","Mixing","mixing.html","make a knob move by itself (modulators: lfo, envelope follower, steps...) right-click any knob (a plugin setting, a fader's pan, a send in the mixer) > modulate with > new lfo on <track> (or envelope follower, steps, random, shape), or tick one the song already has. view > panels > modulators (or the track header's menu > modulators... ) opens a window with the selected track's: a card for each ( + lfo , + envelope , + steps , + random , + shape add more), its settings, and what it moves, each with an amount (-100 to 100 %: how far at its full swing; negative turns it down; +30% to start, -50% for an envelope follower). + target... adds something more for it to move, on any track. adding, ticking and removing are undo steps. lfo : a wave (sine, triangle, saw up, saw down, square, 4 or 8 steps up or down, random, noise). sync type transport and rate type a note value (1/8 to start, 1/4 t...) keep it in time with the song; free uses rate in hz. envelope follower : follows how loud its own track is. on the vocal, with the guitars' reverb send as a target at a negative amount, the reverb ducks while the vocal sings and comes back between lines. gain (12 db to start) sets how readily it moves; attack and release (5 and 150 ms) how quickly; hold , depth , offset and its filters shape it further. steps : a pattern of 2 to 64 steps (8 sixteenths, rising, to start: click or drag the bars), in time with the song. random : a new value each step (1/8 to start), smoothed or not. shape : a shape over each cycle (a bar to start). a modulated knob shows a dot where the modulators have it now. modulators are kept in the song, and their own settings can be automated like any other (their lanes are \"lfo 1: rate\"...). x on a card takes one away; what it moved stays where it was."],["mixing--repeat-a-bar-of-automation-automation-that-loops","Repeat a bar of automation (automation that loops)","Mixing","mixing.html","repeat a bar of automation (automation that loops) draw the pattern in an automation lane over a bar (or any range), select that range (marquee), then right-click the lane > loop the range to the end of the song : the pattern repeats from the range's end to the song's end (where its last clip ends), replacing what was there; the status line says how many times. it's greyed without a range, or when the range reaches the end already. one undo takes it back. (for a pattern that stays editable in one place, use a steps or shape modulator instead.)"],["mixing--a-few-big-knobs-that-move-several-settings-at-once-smart-controls","A few big knobs that move several settings at once (Smart Controls)","Mixing","mixing.html","a few big knobs that move several settings at once (smart controls) select a track and press b ( view > panels > smart controls , or the track header's menu > smart controls... ; a window of its own). set up knobs adds ones to start with for what's on the track (audio and instrument tracks): drive and tone for the amp or a capture player (drive turns the gain up and pulls the treble and level back, so it gets dirtier, not just louder), boost for an overdrive, fuzz for a fuzz, movement for a tremolo, auto-pan, flanger, auto-filter, chorus or phaser, tune for live tune, squash for the compressor (it compresses harder and makes up for it, so it gets denser, not quieter), brightness for an eq (its high shelf), space for the first send. drive, squash and space start at 0, tone and brightness in the middle. one undo step. it measures what the track plays to work out how much drive and squash make up, so turned all the way up the track stays about as loud (squash too with the compressor's mix below 100 %, where its make-up is only partly heard): a few seconds for a long track. or + knob for your own (up to eight; double-click its name to rename it). click a knob to see what it moves: each setting with where the knob at 0 and at 100 puts it (drag or type them; at 100 lower than at 0 turns it down as the knob goes up). add setting... gives it something else to move: any of the track's plugin settings, its fader, pan or sends; the x takes one off. a knob is automated like any setting (its lane is \"smart control: drive\"), and right-clicking it maps it to a controller knob (midi learn). they're kept in the song and in track templates. the settings' own knobs still work: the knob's range moves with them."],["mixing--move-several-faders-together-vca","Move several faders together (VCA)","Mixing","mixing.html","move several faders together (vca) select tracks and choose track > group > group into vca (or right-click > group selected tracks into vca ). the vca's fader turns all of them up or down by the same db while their own faders stay where they are, and its mute mutes them all (all the way down silences them; vcas inside vcas add up). post-fader sends follow it, pre-fader ones don't. each track keeps its own output. drag a track out of the vca to free it; right-click the vca > ungroup vca removes it and leaves the tracks where they are. one undo step each."],["mixing--move-selected-tracks-faders-pans-mutes-and-sends-together-linked-channels","Move selected tracks' faders, pans, mutes and sends together (linked channels)","Mixing","mixing.html","move selected tracks' faders, pans, mutes and sends together (linked channels) select several tracks ( ctrl cmd -click or shift -click their headers or mixer strips), then move one's fader: the others move by the same db, keeping their balance. their pans move by the same amount, a mute mutes them all, and a send moves the same bus's send on the others (on tracks that have one). it works while they're selected (on any of them: move one that isn't selected and only it moves); solos aren't linked. no vca to make. mix > link selected channels turns it off (and on again); on to start with, kept with the song."],["mixing--compare-versions-of-a-mix-mixer-snapshots","Compare versions of a mix (mixer snapshots)","Mixing","mixing.html","compare versions of a mix (mixer snapshots) mix > save mix snapshot... keeps the mix as it is under a name (\"vocal up\", \"less verb\"; \"mix 1\" to start; a name you've used replaces that one): every track's and the master's fader, pan, mute, solo, sends and plugin settings, bypasses included. mix > mix snapshots lists them with when each was saved: choosing one puts that mix back (one undo step), on the tracks and plugins still in the song (it says which aren't). a plugin removed since isn't put back, and one added since is left as it is; a third-party plugin's settings may not undo. the mix you had before is kept as \"before recalling\", so you can go straight back. the song's clips and arrangement don't change (for the whole song, use file > project history snapshots). delete a snapshot takes one away. they're kept in the song."],["mixing--give-the-mix-an-analog-desk-s-sound-console-mode","Give the mix an analog desk's sound (Console Mode)","Mixing","mixing.html","give the mix an analog desk's sound (console mode) mix > console mode puts a console on every track, folder and bus and first on the master: the gentle saturation an analog desk adds to each channel and the mix, rounding off peaks and adding a little warmth, louder signals more, quiet ones left as they are. each console sits last before the fader, adds no delay, and its drive (0 to 100%, 30 at first; 0 leaves the sound alone) sets how much. mix > console mode again takes them all off, with the drives you set. tracks added afterwards don't get one: switch it off and on (every drive goes back to 30%). one undo step."],["mixing--add-plugins-to-a-track","Add plugins to a track","Mixing","mixing.html","add plugins to a track click the + in a track's plugin slots (in the header or the mixer strip) and choose from built-in or plugins (your scanned effect plugins, by maker; scan for plugins... at the bottom). your favourites and the plugins you added lately ( recent , the last eight) are at the top of that menu: right-click a slot > add to favourites to put one there ( remove from favourites takes it off). click a plugin's slot to open its window. the light at the left of a slot says whether the plugin is on: green on, red off (bypassed); click the light to switch it (one undo step), in the track headers, the mixer and a split's paths alike. drag a slot to another place to change the order, or onto another track's slots (in the headers or the mixer) to move it there; hold alt option as you let go to copy it, its settings with it. one undo step each. an effect dropped above a track's instrument goes just after it (before it, it'd get no sound). (the master's and a split's plugins stay where they are.) right-click a slot for open , add to favourites , bypass / turn on , load preset , compare: switch to b and copy a to b (a/b), sidechain from (plugins with a sidechain input), save preset... , run in its own process (third-party plugins), reload (after a crash) and remove . favourites and recent are kept with take 5, for every song. in a short track, ctrl+↑ cmd+↑ makes room. in the mixer, a strip with more plugins than fit shows \"n more\"."],["mixing--add-a-channel-strip-gate-eq-compressor","Add a channel strip (gate, EQ, compressor)","Mixing","mixing.html","add a channel strip (gate, eq, compressor) select a track and choose mix > add channel strip , or the + slot > built-in > channel strip (gate, eq, compressor) : a gate (its threshold low, at -60 db, so nothing's cut until you raise it), eq and compressor go in before the fader, each with its own window (one undo step). click a slot to open its window: set the gate's threshold to shut out noise between notes, shape the tone with the eq's handles, and even out the level with the compressor's threshold, ratio and makeup."],["mixing--know-the-built-in-effects","Know the built-in effects","Mixing","mixing.html","know the built-in effects the + slot > built-in menu, grouped: guitar and bass : amp (clean, crunch, high gain and bass voicings, gain, bass, mid, treble and presence 0-10, level, a cabinet (4x12 british, 2x12 american, 1x12 open back, 4x10 bass, off) or your own impulse response with load ir... ), capture player (nam captures of real amps, pedals and rigs: see \"play a real amp or pedal (nam captures and tone3000)\"), overdrive (a tight boost: put it before the amp to tighten a high-gain palm mute; tight cuts the lows before it clips), fuzz (fuzz, tone from dark to bright, level), octaver (one or two octaves below a single note, as an analogue octave pedal does, mixed with the dry sound), pitch shifter (up or down by up to 24 semitones: an octave down for a bass line), hardware insert. tone : eq (drag the numbered handles on its curve), dynamic eq (bands that cut or boost only while their part of the spectrum is loud), saturator, low pass. dynamics : compressor (threshold, ratio, knee, attack, release, makeup, with a gain-reduction meter, sidechain, and mix for parallel compression), multiband compressor (2-4 bands, each compressed on its own), gate (threshold, range, attack, hold, release), transient shaper (attack and sustain up or down), limiter (gain, ceiling -1 db to start, release, true or sample peaks: for the master). vocals : de-esser (frequency, threshold, range; split-band or wideband; listen to the esses alone), level rider (evens out a vocal before the compressor: target, range, speed and a floor below which it leaves breaths alone), doubler (mix, width, detune, delay), live tune (pitch correction as it plays: key and scale, speed (0 is the robotic, hard-tuned sound) and amount; put it on the armed vocal track to hear yourself in tune while recording). space and movement : reverb, convolution reverb (rooms, halls, plates, or your own impulse response), delay (tempo-synced note values, dotted and triplet, or milliseconds; feedback, mix 30% to start, 100% on a bus; high cut, ping-pong), chorus (rate, depth, width, mix), phaser (rate, depth in octaves, feedback), flanger, tremolo, auto-pan and auto-filter (a filter swept by an lfo, or by how hard you play: the auto-wah). tremolo, auto-pan, flanger and auto-filter follow the song when sync is a note value (1/4, 1/8, 1/8 t...), pulsing on the beat from wherever it plays; free uses rate in hz. plus channel strip (gate, eq, compressor) and split (paths side by side: parallel, by frequency, mid/side) . (the console from console mode isn't in the menu.)"],["mixing--play-a-real-amp-or-pedal-nam-captures-and-tone3000","Play a real amp or pedal (NAM captures and TONE3000)","Mixing","mixing.html","play a real amp or pedal (nam captures and tone3000) add built-in > capture player to a guitar or bass track (where the amp would go). it plays nam captures (.nam files, a1 and a2 models): real amps, pedals and whole rigs captured with neural amp modeler. load capture... lists the ones already on this computer, the last used first, with a search box (type part of a name or a maker; return or a click loads it): every one you've loaded or downloaded from tone3000, the ones in any song's captures folder, and the ones in folders you add with add folder... ( folders shows them; click one to stop listing it). other file... loads one from anywhere, and it's listed from then on. a capture loaded from elsewhere is copied into the song's captures folder, so it goes wherever the song goes. tone3000 reaches tone3000 (tone3000.com), the free library of thousands of them: the first time, choose set the tone3000 key... : sign in on tone3000.com, make a key in settings > api keys (it starts t3k_pub_), and paste it in. it's kept in take 5's settings. tone3000 > pick a tone on tone3000... opens tone3000's catalog in your browser (signing you in the first time): pick a tone and it comes back into take 5, downloaded into the song's captures folder. a tone with several models (gain settings, mics) offers the others in a menu. it plays at once. an amp head captured without its speaker gets a cabinet ( cabinet : one of the amp's, or your own ir with load ir... , listed and copied into the song the same way); an ir tone from tone3000 becomes the cabinet. input (±24 db) drives it harder, gate (off to start) shuts out hum between notes, tone tilts it darker or brighter, output sets its level (captures are brought to about the same loudness first). only mono captures load; one made at another sample rate is converted (adding a little delay). pick a tone and copying into captures need the song saved first. each load is one undo step. the song opens with its captures without the internet. a song package (share) carries your own .nam files, but a tone3000 capture only as its link (its licence lets it be used, not passed on): on a bandmate's computer tone3000 > get it again fetches it. set up knobs gives it drive and tone. ask the assistant for a tone from your tone3000 favourites, downloads or the trending ones, and it can load it; tone3000's free api doesn't let it search the whole library, so for anything else pick it in tone3000's own catalog."],["mixing--use-built-in-plugin-windows","Use built-in plugin windows","Mixing","mixing.html","use built-in plugin windows in a built-in plugin's window, drag a knob up or down (or sideways) to turn it ( shift -drag: in fine steps), double-click or alt option -click it to go back to its default, and type a value in the box under it (or ctrl cmd -click). the power button bypasses the plugin (grey when off), and a | b next to it compares two settings (see \"compare two settings of a plugin\"). right-click a knob for midi learn... and modulate with . some controls (model, cabinet, note value) are menus. each move is one undo step. in the eq, drag a numbered handle for that band's frequency and gain (shift: frequency only), scroll over it for its width ( q ), and double-click it to put its gain back to 0 db. plugins with bands (the multiband compressor, the dynamic eq) show a row per band; bands not in use are faint."],["mixing--squash-only-the-part-of-the-sound-that-s-too-loud-multiband-compressor-dynamic-eq","Squash only the part of the sound that's too loud (Multiband Compressor, Dynamic EQ)","Mixing","mixing.html","squash only the part of the sound that's too loud (multiband compressor, dynamic eq) for palm mutes that boom, a bass whose low end jumps around, or cymbals that get harsh, use the + slot > built-in : multiband compressor : the sound is split into 2-4 bands ( bands , with split 1-3 where they meet) and each band has its own threshold, ratio, attack, release and gain; each row shows how much its band is being turned down. it starts with 3 bands split at 150 hz and 2.5 khz, each at -24 db, 3:1. listen plays one band alone while you set it. with nothing over the thresholds, it leaves the sound as it was. no added delay. dynamic eq : four bands (low shelf, bell or high shelf, or off), each with a frequency and q, that move only while that part of the spectrum is over its threshold , by the ratio , up to the range (below 0 cuts, above 0 boosts). two start on: 250 hz for low-mid boom and 3.5 khz for harshness. listens to: sidechain makes a band follow another track instead (right-click the slot > sidechain from ): a vocal carving its own room in the guitars. the curve shows how far each band can go, and where they all are as it plays."],["mixing--process-parts-of-the-sound-separately-split","Process parts of the sound separately (Split)","Mixing","mixing.html","process parts of the sound separately (split) the + slot > built-in > split puts paths side by side in one slot, each with plugins of its own (two to start), then mixes them back together. a split can't go inside a split. in its window, split by : nothing (the whole sound to each path) : every path gets the whole sound (parallel processing): a clean and a distorted bass, or a squashed copy of the drums under the drums. 2-4 paths; two paths are 6 db louder than one, so turn one down. frequency : each path gets a band (2-4, with split 1-3 where they meet), and the bands add back up to the sound as it was: distort the bass's highs and keep its lows clean. mid and side : the mid (what's the same on both sides) and the side (what's different) each get a path, then are put back: widen only the sides, or eq the middle on its own. left and right : one path each. fewer paths (or bands) removes the last ones with their plugins. each path has a level knob (-60 to +12 db, automatable), m (mute) and s (solo, to hear one band), and its plugins: + adds one, click opens it, right-click for the same menu as a track's slots. plugins in a path are automated, midi-learned and mapped to smart controls like any other, and plugins with latency stay lined up with the other paths. save the whole split (paths and plugins) with save preset... ; it's kept in track templates, and a copied track gets a split of its own."],["mixing--compare-two-settings-of-a-plugin-a-b","Compare two settings of a plugin (A/B)","Mixing","mixing.html","compare two settings of a plugin (a/b) every plugin has two sets of settings to switch between while you set it up: in a built-in plugin's window, a | b switches to b (the first time, b starts as a copy of a, so change it from there) and back (it then reads a | b ); a to b (or b to a ) copies the set you're on to the other. for an installed plugin, right-click its slot > compare: switch to b and compare: copy a to b . each switch is an undo step (undoing one puts the settings back, though the button stays where it is); copying isn't. the other set is kept while the song is open, not in the song."],["mixing--duck-the-bass-with-the-kick-sidechain","Duck the bass with the kick (sidechain)","Mixing","mixing.html","duck the bass with the kick (sidechain) put a compressor (or another plugin with a sidechain input) on the bass, right-click its slot > sidechain from and choose the kick track. the kick now drives the compressor, ducking the bass on every hit. the list has every audio and instrument track but its own; the choice is kept with the song (one undo step). none turns it off. plugins inside a split's paths can't be sidechained."],["mixing--automate-volume-pan-or-a-plugin","Automate volume, pan or a plugin","Mixing","mixing.html","automate volume, pan or a plugin click a track's a button to show its automation lanes: one for each setting already automated, and one more whose drop-down picks any setting (volume to start). to find what's already automated, press a ( view > automation > next track with automation , or the a button under the track headers): it scrolls to the next track that has any automation and opens its lanes, the status line naming what's automated; again goes on to the one after, shift+a back. while a track's automation is showing, touch any of its knobs or faders (in a plugin window, the mixer or the header; a third-party plugin's own knobs while its window is in front) and the lane shows that one, ready to draw; view > automation > automate last touched control , alt+a option+a , opens the lane for the last one you touched even when the lanes are hidden. click in a lane to add a point (on the grid), drag points ( ctrl cmd , ignores the grid), right-click or alt option -click a point to delete it. pick another parameter, including any plugin knob or send level, from the bottom lane's drop-down; clear in a lane's header deletes all of that setting's automation (one undo step). the mode box (the track's, read to start with) sets read (play back), touch (record while you hold a control, then return to what was there), latch (record from the first move until stop) or write (from play, every automated setting is written as it is, touched or not; then the track goes to latch). ride a fader or plugin knob while playing to record it. the header's r and w , and the console layout's toolbar r and w (every track), set read and touch."],["mixing--draw-automation-shapes-over-a-range","Draw automation shapes over a range","Mixing","mixing.html","draw automation shapes over a range select a marquee range (or clips), show the automation ( a ), right-click the lane > draw shape (greyed without a range): fade in, fade out, swell, duck or sine (once a beat), just in that range. reverse and invert work on the range (or the whole lane with none), loop the range to the end of the song repeats it, and copy lane to track puts the same automation on another track's matching parameter. with edit > edit options > automation moves with clips on (off to start, kept with the song), moving a clip takes the automation under it along."],["mixing--send-a-track-to-another-output","Send a track to another output","Mixing","mixing.html","send a track to another output right-click a track > output > an output pair (or master , the main mix), or choose it in the inspector's output . turn on more outputs in settings > audio settings... first (the menu says so while there's only one pair). kept with the song; one undo step. folders have no output of their own. useful for outboard summing, a separate headphone feed or a second set of speakers."],["mixing--compare-my-mix-with-a-reference-track","Compare my mix with a reference track","Mixing","mixing.html","compare my mix with a reference track mix > reference track > choose reference track... and pick a finished song: its loudness and the whole mix's are measured. then mix > reference track > listen to reference (a/b) , alt+r option+r , or mix / ref on the master strip, switches between your mix and the reference at the same place in the song (the button then reads reference , and the loudness readout and analyser measure the reference). with match reference loudness on (it is to start with), the reference is turned down or up (by up to 12 db) to the mix's loudness, so louder doesn't sound better; the mix itself is never changed; measure mix loudness again after changing the mix. the reference also shows as a lane above the tracks (its waveform from the start of the song, its name in the header): click the lane to switch between it and the mix ( view > lanes > reference lane , alt+shift+g shift+option+g , hides it). remove reference track stops using it. the reference never goes into an export. a reference file inside the song's folder is kept by where it is in the folder, so it's found when the song moves to another computer; one elsewhere isn't copied into the song (put it in the song's folder to take it along)."],["mixing--check-the-mix-in-mono-at-low-volume-and-on-the-analyser","Check the mix in mono, at low volume, and on the analyser","Mixing","mixing.html","check the mix in mono, at low volume, and on the analyser mix > mono (or mono on the master strip): hear the mix summed to mono. mix > dim (or dim ): 20 db quieter. mix > master off (matched loudness) (or master off ): see below. mix > analyser : the mix before mono, dim and the listen bus, with the stereo correlation (-1 to +1, red below 0: parts cancelling in mono) under one of four views, chosen at its top right: spectrum (bass on the left), spectrogram (the spectrum over the last seconds, louder brighter, the newest at the right), vectorscope (where the stereo sits: mono is a line up the middle, wide stereo a round cloud, something out of phase a line across) and level history (the level over the last minute, to see a chorus that doesn't lift). it needs the song playing. the loudness readout in the transport bar shows lufs short (the last 3 seconds), lufs int (integrated) and the true peak (red at -1 dbtp or above), with the click when it's on; click it to reset. none of these change an export. mono and dim are for this session only (not saved)."],["mixing--correct-my-room-or-headphones-the-listen-bus","Correct my room or headphones (the listen bus)","Mixing","mixing.html","correct my room or headphones (the listen bus) mix > listen bus... (or listen on the mixer's master strip) holds plugins that only change what you hear from the speakers or headphones, such as room or headphone correction software. + plugin adds one from your scanned third-party plugins (each in its own process), on switches it off to compare, edit opens its window and x takes it off. they come after everything else (mono, dim, the reference) and are never in an export, a bounce or a freeze; the meters show the mix without them. they're kept for this computer, not the song, with their settings. listen on the master strip is lit while one is on; the toolbar's l opens it too. it's on the main outputs only: a headphone mix or a track sent to another output doesn't go through it."],["mixing--hear-what-the-master-s-plugins-do-master-off","Hear what the master's plugins do (Master Off)","Mixing","mixing.html","hear what the master's plugins do (master off) mix > master off (matched loudness) , alt+m option+m , or master off on the master strip plays the mix without the plugins on the master (eq, compressor, limiter, whatever's there), turned up or down to the loudness it has through them. so you hear what the master does to the sound, not just that it's louder. the first time, and after any change to the song, it renders the mix twice to measure the loudness (over the loop if looping, else the whole song), which takes a few seconds; the status line says how much it turned the mix by. press it again for the master back. it changes only what you hear (the click too): exports, the assistant's analysis and the saved song keep the master, and there's nothing to undo. a plugin added to the master while it's on isn't bypassed: switch it off and on again. with no plugins on the master it has nothing to do (and says so); it matches by up to 24 db."],["mixing--bounce-a-track-to-audio-bounce-in-place","Bounce a track to audio (Bounce in Place)","Mixing","mixing.html","bounce a track to audio (bounce in place) select tracks and choose track > bounce in place ( ctrl+b control+b ), or right-click a track > bounce in place : what they play, effects and all (their tails too), becomes a 24-bit wav in the song's audio folder on new tracks, with the originals' fader, pan and sends, and the originals are muted. with a marquee range, track > bounce in place (or bounce range in place ) does just those bars: the original's clips are cut at the range's edges and muted only inside it. one undo step."],["plugins--find-my-installed-plugins-scan","Find my installed plugins (scan)","Plugins","mixing.html","find my installed plugins (scan) settings > plugins... opens the plugins window: its options... button scans for installed plugins: vst3, audio units and clap (the clap folders in library/audio/plug-ins); vst3 and clap on windows (from c:\\program files\\common files\\vst3 and the common files\\clap folders). the scan runs in helper processes, so a plugin that crashes while being scanned doesn't take take 5 with it. after scanning, effects appear under plugins in the + slot menu and instruments under track > new instrument track... > plugins . scan for plugins... is also at the bottom of the + slot menu."],["plugins--save-and-load-plugin-presets","Save and load plugin presets","Plugins","mixing.html","save and load plugin presets right-click a plugin's slot > save preset... and give it a name; load preset lists the saved ones for that plugin. works for built-in and third-party plugins, on top of the plugin's own presets. presets are kept in take 5's settings folder, so they're there in every song (a plugin's vst3 and au copies have their own lists). load preset is greyed while there are none. a split's preset keeps its paths and their plugins. to save a whole track's plugins and settings at once, use right-click the track > save as track template... ."],["plugins--a-plugin-crashed-amber-light-with-a","A plugin crashed (amber light with a !)","Plugins","mixing.html","a plugin crashed (amber light with a !) every third-party plugin runs in a helper process of its own (\"take 5 plugin host\"), so when one crashes or hangs, the song keeps playing: the plugin's light turns amber with a \"!\", audio passes straight through it, and a message says what happened. click the slot to reload it with its last settings, kept up to date in the background (or right-click > reload (it crashed) ). settings > run plugins in their own processes (on to start with) turns this off for all plugins (they then load inside take 5, and the song's plugins reload); right-click a third-party plugin's slot > run in its own process sets it for that plugin, wherever it's used (kept with take 5)."],["plugins--use-intel-only-plugins-on-an-apple-silicon-mac","Use Intel-only plugins on an Apple silicon Mac","Plugins","mixing.html","use intel-only plugins on an apple silicon mac intel-only plugins run under rosetta in their own helper process: they're found by the scan and work like any other. their slot menu says \"runs under rosetta (an intel-only plugin)\", and they always run in their own process (they need the take 5 plugin host that comes with take 5). nothing to set up: rosetta must be installed (macos offers it the first time an intel app runs)."],["plugins--put-an-effect-on-one-clip-only-clip-effects","Put an effect on one clip only (clip effects)","Plugins","mixing.html","put an effect on one clip only (clip effects) for a reverb or echo throw on one word, de-essing one line, or another amp on one part, without automating the whole track: right-click the audio clip > clip effects > add an effect... and pick it, as for a track. it plays on that clip's audio only, before the track's own effects, and goes with the clip when it's moved, copied or split. clip effects lists the clip's effects: each has open , bypass and remove (the menu reads \"clip effects (2)\" with two). a clip with effects says \"fx 1\" (how many) on its name strip. the clip's fades are on its audio, before its effects, so a reverb or delay on it rings on past the clip's end."],["plugins--render-a-clip-s-effects-into-it-and-take-the-render-back","Render a clip's effects into it, and take the render back","Plugins","mixing.html","render a clip's effects into it, and take the render back right-click a clip with effects > clip effects > render into the clip : the clip as it plays, its effects included (a reverb's tail too: the clip gets longer by as much as it rings on, up to 4 seconds and the next clip on the track), becomes a new file in the song's audio folder and a plain clip in its place (\"rendered\" on its name strip). it saves cpu, and frees the effect to edit the audio further. clip effects > take back the render puts the clip back as it was, its effects playing live again, at any time, even after saving and reopening. one undo step each."],["plugins--use-outboard-gear-on-a-track-hardware-insert","Use outboard gear on a track (Hardware Insert)","Plugins","mixing.html","use outboard gear on a track (hardware insert) add built-in > guitar and bass > hardware insert to a track. choose the interface output your pedal or outboard unit is connected to and the input it comes back on (it starts on the second output and the last input; with one output it waits for you to choose, so nothing feeds back), and press measure so it stays in time with the other tracks: it plays clicks out and listens for them, so turn the gear's output down or measure with a cable first. the result (in ms and samples) is kept with the song. the track then plays through the gear; bypassing the insert plays it dry."],["finishing-and-exporting--export-the-mix-as-wav-mp3-or-flac","Export the mix as WAV, MP3 or FLAC","Finishing and exporting","finishing-and-sharing.html","export the mix as wav, mp3 or flac file > export... , ctrl+e cmd+e , with export set to the mix (one file) : formats : tick one or more of wav (ticked to start with), aiff, flac and mp3: a file of each. quality : 16 or 24-bit (24 to start) for wav, aiff and flac; for mp3, 128, 192, 256 or 320 kbit/s (320 to start; constant bit rate, 16-bit). sample rate : 44.1, 48, 88.2 or 96 khz (the audio interface's rate to start with). an mp3 can't be 88.2 or 96: it's written at 44.1 or 48. range : whole song , or loop range (greyed until there's one: drag in the ruler). the whole song goes on past the last clip while reverbs and delays ring on, until they've died away (10 seconds at most); a loop range stops at its end. loudness : as mixed , or a target (see \"export at a loudness target for streaming\"). mp3 tags : title (the song's name to start with), artist, album and year, for an mp3. the artist is remembered for every song; the rest goes back to how it was each time. export... asks where (the song's folder, \"<song>.wav\"); each other format gets the same name with its own extension, replacing a file of that name without asking. the export respects mute and solo, has every plugin on (even in low-latency mode), is always stereo, and leaves out the click, the reference, mono, dim, master off and the listen bus. the export window shows each file as it's written with a progress bar and cancel (which deletes the file being written). when it's done it says export finished , with the integrated loudness, true peak and loudness range of the first file that isn't an mp3: open in finder ( open in explorer on windows) opens the folder with the file selected, close window closes it. mp3 works out of the box and windows: the encoder is built in."],["finishing-and-exporting--export-at-a-loudness-target-for-streaming","Export at a loudness target for streaming","Finishing and exporting","finishing-and-sharing.html","export at a loudness target for streaming in file > export... , set the loudness to -14 lufs (streaming) , -16 lufs (podcasts, gentler) or -23 lufs (broadcast) instead of as mixed . the export is turned up or down to that loudness (one change of level, no limiting), but never so far that its true peak goes over -1 dbtp: a mix with loud peaks comes out quieter than the target (check the loudness the finished window shows). for a louder master, put the limiter on the master and push its gain while watching the true peak reading in the transport bar. with each section , each file is brought to the target on its own. stems keep their balance: loudness is greyed for them."],["finishing-and-exporting--master-the-song-for-streaming-with-the-assistant","Master the song for streaming (with the assistant)","Finishing and exporting","finishing-and-sharing.html","master the song for streaming (with the assistant) ask the assistant: \"master this for streaming, punchy\", \"master it like the reference, -14 lufs\". it measures the mix (loudness, true peak, and the balance in third-octave bands, compared band by band with the reference track if you've chosen one, at matched loudness), sets up the master's eq, compressor and limiter from what it measured (a dynamic eq or multiband compressor for problems that come and go, a split by mid/side for width), then measures again and adjusts: within 0.5 lu of the target (-14 lufs unless you say another) with the true peak at or under -1 db. it's one request, so one undo, ctrl+z cmd+z , takes it all back. then use master off on the master strip ( mix > master off (matched loudness) ) to hear whether the master helps."],["finishing-and-exporting--export-stems","Export stems","Finishing and exporting","finishing-and-sharing.html","export stems in file > export... , choose stems (one file per track, folder and bus) , then a folder: a \"<song> stems\" folder is made in it, with a file per top-level track, folder (everything in it) and bus, \"<song> - <track>.wav\" (and the other formats ticked). stems leave out their sends (those are in the bus stems) and the master's plugins and fader, so dropped into another music app at the same start they add up to the mix before the master. muted tracks get none; drum channels and tracks inside a vca get stems of their own. range applies (the whole song with its tail); loudness and the mp3 tags don't. when it's done it says how many files."],["finishing-and-exporting--export-each-section-as-its-own-file","Export each section as its own file","Finishing and exporting","finishing-and-sharing.html","export each section as its own file add section markers first, then in file > export... choose each section (one file per section) (it says how many): one numbered file per section, from marker to marker (\"<song> - 1 verse.wav\"; \"01\", \"02\" with ten or more), in a \"<song> sections\" folder made in the folder you choose. anything before the first marker isn't in one; the last runs to the end of the last clip. range is greyed; a loudness target applies to each file; an mp3's title tag gets the section's name. the option is greyed out until the song has section markers (see \"add and name sections (intro, verse, chorus)\")."],["finishing-and-exporting--export-just-part-of-the-song","Export just part of the song","Finishing and exporting","finishing-and-sharing.html","export just part of the song set a loop range by dragging in the ruler and choose loop range in file > export... . to save what each track plays in a marquee range as separate files, use file > export other formats > export range as wav... (greyed without a marquee range): a 24-bit wav per track, through its effects or instrument and with their tails, but at an even level (no fader, pan, sends or master), named \"<track> <start>-<end>.wav\" by bar and beat, in the song's exports folder to start with (one track asks for a file, several for a folder)."],["finishing-and-exporting--put-songs-together-as-an-album-or-ep","Put songs together as an album or EP","Finishing and exporting","finishing-and-sharing.html","put songs together as an album or ep file > album... opens a window (choose it again to close it: an album not saved is gone): the album's title , artist and year , and its songs. add songs... adds songs (their .tracktionedit files) at the end; move up , move down and remove put them in order (each song's title is its file's name). for the selected song, then : a gap of some seconds (2 to start) before the next, or crossfade over some seconds into it (an even crossfade; the last song has neither); trim (db) , -24 to +12, turns it up or down by hand after matching. match to sets the loudness every song is brought to: -14 lufs (streaming) (to start with), -16 lufs (podcasts, gentler) , -11 lufs (loud) , -9 lufs (very loud) or off: as they're mixed . whatever the choice, no song goes over -1 db true peak: one that would is left a little quieter, and says so. measure shows each song's loudness now. render album... asks for a folder and writes 24-bit, 44.1 khz files there, replacing ones of the same name: a wav per song (\"01 hearts explode.wav\"...), matched, with its reverb's tail (up to 4 seconds, until it's silent), and its title, artist, album, year and track number in it; one wav of them all (\"<album>.wav\"), in order with the gaps and crossfades, with a marker where each song starts; a cue sheet (\"<album>.cue\") beside it, to burn a cd or for a distributor. then a box lists each song's loudness and true peak and the whole album's length. each song is rendered from its file, through its own master, so a change to a mix is in the next render (the open song is saved first if it's one of them). save... keeps the album as a .t5album file (it offers the folder your songs are in); open... brings it back. the album remembers where each song is: a song moved since shows red, \"(missing)\", and has to be added again."],["finishing-and-exporting--hand-a-song-to-another-music-app-dawproject","Hand a song to another music app (DAWproject)","Finishing and exporting","finishing-and-sharing.html","hand a song to another music app (dawproject) file > export other formats > export dawproject... saves the song as a .dawproject file, the open format many music apps read: the tracks and folders (as submixes), buses (as effect channels), midi clips and their notes, audio clips (the audio files go inside it) with their fades, each channel's fader, pan, mute, solo and sends, the automation of faders, pans and sends, the section markers, and the tempo (its changes as tempo automation; only the starting time signature). it goes in the song's exports folder to start with. installed vst3 plugins go across with their settings (a few older ones by name only); clap and au plugins by name (load their settings again there); a bypassed plugin stays bypassed. the built-in eq and compressor become the other app's own; take 5's other effects and instruments (the amp, the delay...) can't go across, and are listed in each track's comment. every folder goes as a submix (a vca too). not carried: the master's plugins (its fader and pan are), clip gain, and looped audio clips; stretched or reversed clips go as recorded. afterwards take 5 says what didn't go across (\"exported, mostly\"). for an app that reads aaf but not dawproject (and video editors), export an aaf instead."],["finishing-and-exporting--export-an-aaf-session","Export an AAF session","Finishing and exporting","finishing-and-sharing.html","export an aaf session file > export other formats > export aaf... writes the song as an aaf session: audio tracks with their clips, fades and crossfades, clip gain, volume, pan and the markers. it asks first where the audio goes: in the aaf or wav files beside it (a \"<name> audio\" folder, a mono wav per channel), then where to save (the song's exports folder to start with). clips an aaf can't describe (stretched, warped, reversed, looped, pitch-shifted, with envelopes or clip effects) go out rendered as they sound. midi, muted tracks and clips, plugins, sends and automation don't go, and the export says so, with how many tracks and clips went, and any track split in two (mono and stereo clips, or overlapping ones). it starts at 00:00:00:00 at 25 frames a second. a song imported from an aaf that started at a timecode starts there again. for midi parts, use file > export other formats > export midi file... ."],["sharing-with-bandmates--put-my-name-on-parts-and-comments","Put my name on parts and comments","Sharing with bandmates","finishing-and-sharing.html","put my name on parts and comments settings > your name... : the name on the parts you send and the comments you write (\"alan: retake this bar\"). it starts as your computer account's first name. set it once on each computer (it's for every song), before you send parts or leave comments, so bandmates can see who played what. a changed version of a track you have arrives as an alternative named after them. changing it later doesn't change earlier comments or parts."],["sharing-with-bandmates--send-a-song-to-a-bandmate-song-package","Send a song to a bandmate (song package)","Sharing with bandmates","finishing-and-sharing.html","send a song to a bandmate (song package) file > share with bandmates > save song package... makes one .take5song file (on the desktop to start with) with the song as it is now (unsaved changes too) and only the files it uses: the audio of its clips and takes, sampler and drum kit samples, and the capture player's captures and cabinets (a tone3000 tone goes as a link, downloaded again at the other end). not the backups, snapshots or exports. up to 4 gb of audio: for more, send parts a few tracks at a time. send it any way you like. double-clicking it (or file > open song... ) closes the song you have open (asking to save) and opens it as a song of its own in music/take 5 (\"<song> (2)\" if the name is taken), with its takes, drum kits and plugin settings. its third-party plugins have to be installed on that computer too."],["sharing-with-bandmates--work-on-a-song-through-a-shared-band-folder","Work on a song through a shared band folder","Sharing with bandmates","finishing-and-sharing.html","work on a song through a shared band folder on your computer: file > share with bandmates > share in band folder... and choose a folder your band shares (one a cloud or sync service keeps the same on everyone's computer). a folder named after the song appears there with the package (\"<song> - from <you> <date>.take5song\") and a parts folder. take 5 remembers the band folder for this song on this computer. a bandmate double-clicks the package there: it opens as their own copy, knowing the band folder (if they opened a copy from elsewhere, they choose it with share in band folder...). they record a part, then share with bandmates > send parts... : every track is listed, the new ones (not in the song when it was shared, sent or received) ticked and marked \"(new)\"; send to band folder (or save as a file... to send it another way). inputs aren't sent. take 5 checks the folder every 20 seconds or so (not while recording or while a window is asking something). when parts arrive, \"<name> sent <tracks> for <song>\" asks to import them, the oldest first: import , later (asked again next time the song opens) or don't import . nobody's song file is ever overwritten: only .take5song and .take5parts files go in the shared folder, and sharing again adds another package."],["sharing-with-bandmates--import-parts-a-bandmate-sent","Import parts a bandmate sent","Sharing with bandmates","finishing-and-sharing.html","import parts a bandmate sent double-click a .take5parts file, or file > share with bandmates > import parts... . new tracks land as new tracks, where they were played (on the same bars even if the tempo changed); a new version of a track you already have arrives as an alternative of it, named after who played it, playing, its takes there to comp (right-click the track > alternatives ); a track that hasn't changed is left as it is. new tracks go in the folder they were in, if you have it. their audio is copied into the song's audio folder, and their comments added. a box says what came in; ctrl+z cmd+z takes it all out again. parts for another song are refused (open the song they're for first)."],["sharing-with-bandmates--leave-a-comment-at-a-point-in-the-song","Leave a comment at a point in the song","Sharing with bandmates","finishing-and-sharing.html","leave a comment at a point in the song right-click the sections lane > add comment here... and type it: a dot with your initial, signed with your name, at that point (on the grid; it stays on its beat if the tempo changes). hover over the dot to read it (who, what, where); right-click it > remove comment . both are undo steps. comments go to bandmates with the parts you send and in a song package, and removing one removes it for them too."],["backups-history-and-recovery--undo-several-steps-at-once","Undo several steps at once","Backups, history and recovery","finishing-and-sharing.html","undo several steps at once edit > undo , ctrl+z cmd+z , and redo , ctrl+shift+z shift+cmd+z ; the menu names the step. edit > undo history lists the last 25 steps: choose one to go back to before it in one go. fader, pan, send and plugin-knob moves are undoable too (one step per drag), and each assistant request is a single step. saving isn't a step: after a save, undo still undoes your last edit. insert silence, delete and close gap and deleting a range are one step each. the history goes when the song closes (and after clean up unused audio... , restore or recover). while the assistant is working, stop it first. for versions from earlier saves, see \"go back to an earlier save\"."],["backups-history-and-recovery--how-autosave-and-backups-work","How autosave and backups work","Backups, history and recovery","finishing-and-sharing.html","how autosave and backups work while there are unsaved changes, take 5 saves a recovery copy every 2 minutes (not while recording): a hidden file beside the song, gone when you save or close without saving. each file > save ( ctrl+s cmd+s ) keeps the previous save in the song's backups folder, \"<song> <date> <time>\" (at most one every 5 minutes, the newest 20). the song is also saved when a recording stops."],["backups-history-and-recovery--recover-after-a-crash","Recover after a crash","Backups, history and recovery","finishing-and-sharing.html","recover after a crash if take 5 stopped without saving (a crash, a power cut, a force quit), the next time you open the song it offers the recovery copy: recover changes brings your unsaved work back; open last save opens the song as last saved and drops the recovery copy. recovering puts the recovered song in place of the song file at once, and the last save goes to the backups folder: to go back to it, use file > revert to backup (closing without saving doesn't). a recovered song counts as unsaved until you save it, so closing it asks whether to save; the recovery isn't offered again."],["backups-history-and-recovery--go-back-to-an-earlier-save","Go back to an earlier save","Backups, history and recovery","finishing-and-sharing.html","go back to an earlier save file > revert to backup lists earlier saves (not snapshots) by time, newest first; pick one and revert (unsaved changes are lost; the current save is kept as a backup). file > song history... lists backups (saved) and snapshots (snapshot), newest first. select one and press listen (or double-click it) to hear 30 seconds of that version from the playhead (or the loop) without changing the song ( stop ends it). restore... makes it the song again; the song as last saved is kept as a backup. the undo history goes with a restore."],["backups-history-and-recovery--bring-back-a-deleted-track","Bring back a deleted track","Backups, history and recovery","finishing-and-sharing.html","bring back a deleted track file > song history... , pick a save from before you deleted it, then bring back track : tracks you've deleted since are listed under \"deleted since then\". it comes back where it was (in its folder, if that's still there), with its clips and plugins. as it was then (a copy) brings back a copy of how a track used to be, \"<track> (earlier)\", after it. ctrl+z cmd+z takes it away again. if its audio has been cleaned up since, it says how many clips lost theirs."],["backups-history-and-recovery--save-a-named-snapshot","Save a named snapshot","Backups, history and recovery","finishing-and-sharing.html","save a named snapshot file > save snapshot... (or save snapshot in song history) keeps the song as it is now under a name (\"before the rewrite\"), unsaved changes included (the song file itself isn't saved). it's a file in the song's snapshots folder (a name already used gets a number). snapshots show marked snapshot in file > song history... and are kept until you delete them from that folder."],["backups-history-and-recovery--keep-a-second-copy-on-another-disk-or-in-the-cloud","Keep a second copy on another disk or in the cloud","Backups, history and recovery","finishing-and-sharing.html","keep a second copy on another disk or in the cloud settings > second copy of backups... (or second copy... in song history, where it shows where the copy goes): choose a folder on another disk or one a cloud service syncs, outside the song's folder. it's one folder for every song. after each save (and each snapshot), a folder named after the song's folder there gets everything in it (song file, backups, snapshots, audio, exports), in the background, copying only what's changed. backups dropped from the song are dropped from the copy; deleted audio and snapshots stay there. with a folder chosen, the same command offers choose another folder... , turn off and show in finder ( show in explorer on windows). if the disk isn't connected, the status line says the copy wasn't made."],["backups-history-and-recovery--start-songs-from-a-template","Start songs from a template","Backups, history and recovery","finishing-and-sharing.html","start songs from a template set up a song the way you like to start (band tracks, inputs, buses, tempo, click), then file > save as song template... and name it (a name you've used replaces that template): tracks, plugins, buses and settings, no clips, takes or sections, nor its comments or what ties it to a shared song. file > new song from template starts from it, and settings > template for new songs makes file > new song... always use it ( none (one audio track) goes back: one audio track, 120 bpm, 4/4). a new song from a template starts with the playhead at the start, wherever it was when the template was saved. templates are kept with take 5 (its templates folder), for every song."],["backups-history-and-recovery--tidy-up-a-song-folder","Tidy up a song folder","Backups, history and recovery","finishing-and-sharing.html","tidy up a song folder file > collect audio into song copies the audio its clips use from elsewhere into its audio folder, so the folder works on its own (one undo step; it says how many files, and any missing). file > clean up unused audio... lists files in the audio folder that nothing uses (not the song's clips, takes or alternatives, nor its backups and snapshots) and, on move to trash , moves them to the trash (recycle bin on windows). it clears the undo history."],["backups-history-and-recovery--find-files-a-song-is-missing","Find files a song is missing","Backups, history and recovery","finishing-and-sharing.html","find files a song is missing when a song opens and some of its files aren't where it says (it came from another computer, or a folder was moved or renamed), a message lists them: its clips' audio, the capture player's captures and cabinet irs, the reference track. the rest of the song plays. find in folder... looks through a folder you choose, and the folders in it, for each by its file name and points the song at what it finds (one undo step); later leaves them, and the message comes back the next time the song opens. file > find missing files... does it any time."],["the-assistant--set-up-the-assistant","Set up the assistant","The assistant","help.html","set up the assistant the assistant makes changes you ask for in plain words, through claude code on your own claude plan, or free through google's gemini. with claude code: install claude code from claude.com/code. open terminal (on windows, command prompt), type claude, and sign in once. in take 5, view > panels > assistant , ctrl+alt+a option+cmd+a . take 5 looks for claude code when it opens: if you installed it while take 5 was open, press look again in the panel (shown while there's nothing to run on), or ... > look for claude code again , or reopen take 5. with gemini (no claude plan needed): settings > assistant... , then get a free key... : sign in to google ai studio with a google account and create a key (no card needed). paste it into gemini key , set use to gemini (or leave it on automatic , which uses claude code when it's installed, else gemini when there's a key) and press save . with use on claude code it never falls back to gemini. open the assistant: view > panels > assistant . gemini model is the model it asks (gemini-flash-latest, the newest flash, unless you change it; left empty, it's that); choose model... lists the models your key can use (the key first), to pick one. after save , the status line says what the assistant runs on. gemini's free tier has limits per minute and per day: when one is reached the assistant says so, and waits a moment when the wait is short. when google's servers are busy (\"high demand\") it asks again a couple of times, then asks the lighter flash-lite model instead (and says so in the chat); with no answer within a minute it switches to flash-lite at once. once it has switched, the next 10 requests go straight to flash-lite, then it tries flash again. if flash-lite is busy too, it says to try again in a few minutes. google may use what's sent on the free tier to improve its products. the key is kept in take 5's settings on this computer (not encrypted) and never written to the log. the panel's ... menu shows what it runs on, and has assistant settings... . the assistant needs a song open."],["the-assistant--ask-the-assistant-to-change-the-song","Ask the assistant to change the song","The assistant","help.html","ask the assistant to change the song type a request in the assistant panel and press return : \"compress the bass a bit\", \"make the chorus 2 db louder\", \"add a bar of silence before the outro\", \"pan the rhythm guitars wider\", \"transpose the arp up an octave\", \"set the tempo to 120\". it says what it changed. each request is one undo step: ctrl+z cmd+z takes the whole request back (edit > undo names it \"assistant: ...\"). a menu command it runs is an undo step of its own, and settings it changes (the audio device, the theme, the click) aren't undone. while it works, the box shows what it's doing and for how long, and send becomes stop : it stops after the step it's on, keeping what it changed so far (one undo step). a reply too long for the panel opens at its start. with gemini, a request that takes more than 25 steps stops: ask for less at once."],["the-assistant--ask-the-assistant-about-the-song-or-about-take-5","Ask the assistant about the song or about Take 5","The assistant","help.html","ask the assistant about the song or about take 5 ask questions too: \"why does the mix sound muddy?\" makes it analyse the mix before answering, without changing anything. it can also answer \"how do i...\" questions from this guide, find menu commands and their shortcuts, run commands (show the mixer, start the tuner, turn on the loop), and read and change settings. it asks before changing anything that could cut the sound, such as the audio device or buffer size, and changes it only once you've said yes. besides those, it can switch midi inputs and outputs, the click's sound and output, the count-in and pre-roll, and the theme. it knows every plugin you have, built in and installed: it can add one by name, turn any of its knobs (\"set the reverb's mix to 30%\"), load or save its presets, and put another instrument on a track (\"give the keys a grand piano sound\"). it won't open, close or save songs, quit, or undo for you. click one of its messages and press ctrl+c cmd+c to copy it (as plain text); ctrl+a cmd+a copies the whole conversation; right-click for copy and copy conversation ."],["the-assistant--what-the-assistant-can-and-can-t-do","What the assistant can and can't do","The assistant","help.html","what the assistant can and can't do it works only on the open song and take 5's own commands and settings: it can't open files you choose, run other programs or touch anything outside the app (it writes only into the song's folder: a dawproject export, a tone3000 tone it downloads). only the song's details (track names, levels, plugins, notes, lyrics, measurements), the guide's text and your audio devices' names go to claude (or gemini), never audio. it remembers the conversation until you choose ... > clear conversation , open another song, save the assistant's settings, or quit. if claude code isn't installed, isn't signed in, gemini's key is wrong or its limit is reached, or the internet is off, the panel says so: a request that fails before it starts leaves the song alone; one that stops partway keeps what it changed (one undo step). on windows, a request to claude code can be about 32,000 characters at most."],["troubleshooting--i-can-t-hear-anything","I can't hear anything","Troubleshooting","help.html","i can't hear anything check settings > audio settings... : the right output device, its output channels ticked, and press test for a tone. check the master fader and that mix > dim isn't on; check nothing is soloed ( mix > unsolo all ) or muted ( mix > unmute all ). check the track's output (right-click > output ) is master or an output you're listening to. a deactivated track (greyed out) is silent: right-click > activate track . if something went extremely loud (over +12 db, or broken audio from a plugin), the output mutes itself for 2 seconds to protect your ears and the status line says so."],["troubleshooting--i-can-t-hear-my-guitar-or-mic-while-recording","I can't hear my guitar or mic while recording","Troubleshooting","help.html","i can't hear my guitar or mic while recording in settings > audio settings... , the interface is the input device and its input channel is ticked. the track's input menu shows that input (not \"no input\"). the track is armed (its r button, not the r key): its meter should move when you play. if not, check the interface's gain and cable. (an input feeds one track at a time: choosing it on another track takes it from this one.) input monitoring (the headphones button) is auto or on , not off . it belongs to the input: every track on that input follows it. on a mac, take 5 must be allowed the microphone: system settings > privacy & security > microphone. some interfaces have a direct-monitor knob or switch; if you hear yourself twice, set monitoring to off ."],["troubleshooting--my-recording-is-late-or-out-of-sync-with-the-click","My recording is late or out of sync with the click","Troubleshooting","help.html","my recording is late or out of sync with the click take 5 moves recordings earlier by the latency the interface reports. if takes still land late or early, measure the real round trip: a cable from an output straight to an input, settings > recording latency... , measure (see \"measure recording latency so takes line up\"); it's kept for each input, so measure each one you record from. plugins that delay the sound are compensated on playback; while recording, transport > low-latency mode keeps what you hear immediate. bluetooth headphones lag too much to record with."],["troubleshooting--i-hear-crackles-clicks-or-dropouts","I hear crackles, clicks or dropouts","Troubleshooting","help.html","i hear crackles, clicks or dropouts raise the buffer size in settings > audio settings... (for example 128 to 256, or 512 for mixing). on windows, use the interface's asio driver rather than windows audio or directsound. find the heavy ones in view > panels > cpu use (or click the cpu reading at the bottom right), then freeze or deactivate them (right-click a track > freeze or deactivate track ). clicks at clip edits: turn on edit > edit options > snap edits to zero crossings , or add short fades. clicks only in a mix that's very loud may be clipping: watch the master meter and the true peak readout."],["troubleshooting--my-midi-keyboard-doesn-t-play-anything","My MIDI keyboard doesn't play anything","Troubleshooting","help.html","my midi keyboard doesn't play anything plug it in: take 5 finds a midi keyboard within a few seconds, even while it's open, and listens to every one unless it's switched off in midi > midi inputs (ticked: listened to). if it still plays nothing, unplug it and plug it back in, or quit and reopen take 5. a bluetooth one has to be paired first: bluetooth midi... in settings > audio settings... (mac only). play an instrument track ( track > new instrument track... ), not an audio track, and arm it (its r button). the instrument track's input should be \"all midi ins\" or your keyboard. check the instrument makes sound: click a key on the piano roll's keyboard, or a drum machine pad. a bundled instrument only plays its own range: musical typing dims keys out of reach. notes stuck on? transport > panic , or double-click the play button."],["troubleshooting--my-keyboard-plays-some-notes-twice","My keyboard plays some notes twice","Troubleshooting","help.html","my keyboard plays some notes twice some keyboards with worn contacts send a note twice. settings > ignore notes sent twice by and tick the keyboard (kept for that keyboard): a second note-on for a key still held, within 40 ms, is dropped, so a doubled note sounds and records once while fast repeated notes still work. for notes already recorded, open them in the midi editor and choose midi > remove doubled notes (notes on one key starting within 40 ms become one)."],["troubleshooting--notes-or-sounds-are-stuck-on","Notes or sounds are stuck on","Troubleshooting","help.html","notes or sounds are stuck on transport > panic (it has no key until you give it one), or double-click the play button: every plugin is reset and all notes, sounds and the sustain pedal are released on every track and midi input, including plugins in their own processes. if a note keeps sticking, check the keyboard's sustain pedal and cable, and see \"my midi keyboard doesn't play anything\"."],["troubleshooting--a-plugin-is-missing-from-the-menu","A plugin is missing from the menu","Troubleshooting","help.html","a plugin is missing from the menu scan again: settings > plugins... , then options... > scan for new or updated vst3, audiounit or clap plug-ins , and choose the folders to look in. each plugin is scanned in a separate process: one that crashes (twice) or takes more than 2 minutes is skipped, listed at the end, and tried again next time. options... also removes plugins from the list (the selected ones, or those no longer there). check its format:, vst3, audio units or clap; on windows, vst3 or clap. check it's installed where plugins go:, library/audio/plug-ins (in your home folder or the disk's); on windows, c:\\program files\\common files\\vst3 (or clap), or the same in %localappdata%\\programs\\common. instruments are listed under track > new instrument track... > plugins , effects under the + slot > plugins ."],["troubleshooting--space-or-r-doesn-t-do-anything","Space or R doesn't do anything","Troubleshooting","help.html","space or r doesn't do anything space plays and stops, r records. single-key shortcuts don't work while you're typing in a text box (a track name, a value box): click an empty part of the tracks first. with no song open, there's nothing to play. if you changed the key set, check settings > key commands... or the cheat sheet ( ctrl+/ cmd+/ ). (while musical typing is on, the letter keys of its keyboard play notes; space and r still work.)"],["troubleshooting--send-a-bug-report","Send a bug report","Troubleshooting","help.html","send a bug report help > show log files opens the folder with this launch's log selected (\"take 5 2026-10-31 14-05-12.log\": the date and time it opened). send it to alan with what you did; it already has your computer, system, audio device, midi inputs, how the last launch ended and everything the app did. the last 20 launches' logs are kept. for a plugin problem, send \"plugin hosts.log\" from the same folder too. if take 5 won't start, the logs are in ~/library/logs/take 5 and %appdata%\\take 5\\logs on windows. help > detailed log (ticked while on, and remembered) writes more, the plugins' processes too, for chasing a problem."],["windows-and-mac-differences--shortcuts-and-menus-on-windows","Shortcuts and menus on Windows","Windows and Mac differences","help.html","shortcuts and menus on windows where this guide says cmd, use ctrl; where it says opt, use alt (ctrl+s saves, ctrl+z undoes). the two shortcuts that are control on the mac, bounce in place and mute notes, are ctrl+b and ctrl+m on windows. return is enter. the menu bar is inside the take 5 window (open its menus with the mouse; alt and f10 don't). file > exit , ctrl+q, quits (on the mac, take 5 > quit take 5 ). finder is explorer, and the trash is the recycle bin. in the key sets, where a mac key and a control key become the same ctrl key, the second command gets ctrl+alt instead (set b's midi editor, ctrl+alt+=; mute notes in sets c and f, ctrl+alt+m)."],["windows-and-mac-differences--where-take-5-keeps-things","Where Take 5 keeps things","Windows and Mac differences","help.html","where take 5 keeps things songs: music/take 5 (mac), music\\take 5 (windows). settings, templates and presets: ~/library/take 5 (mac), %appdata%\\take 5 (windows). the demo song: the windows installer puts it in music\\take 5\\take 5 demo; on the mac, copy it from the disk image. logs: ~/library/logs/take 5 (mac), %appdata%\\take 5\\logs (windows). backups: in each song's own backups folder, on both."],["windows-and-mac-differences--what-s-different-on-windows","What's different on Windows","Windows and Mac differences","help.html","what's different on windows audio: asio (with your interface's driver), windows audio or directsound, instead of core audio. plugins: vst3 and clap (audio units are mac-only). midi: no bluetooth midi keyboards (pairing is mac-only), and for midi between apps you need a virtual midi port tool (the mac has the iac driver built in). printing sheet music opens the pdf in your pdf viewer to print from. the bluetooth-headset microphone switch and rosetta for intel-only plugins are mac-only. the first launch may show smartscreen's \"windows protected your pc\": more info , run anyway . about take 5 , check for updates... and check for updates at startup are in the help menu (on the mac, in the take 5 menu), and an update installs itself and opens take 5 again; on the mac you drag the new one into applications. the installer adds take 5 to the start menu (and, if you like, the desktop); uninstall it from settings > apps. a new song's folder name loses dots and spaces at its end (windows doesn't allow them). everything else (songs, templates, song packages, parts) works the same on both. a song folder copied from one to the other opens with its audio: songs are saved the way both read (a song saved by an older version on windows is read on the mac too). audio kept outside the song's folder (by a full path, such as c:\\... or a network drive) isn't found on the other system: file > collect audio into song first."]];
var T5_AREAS = {"getting-started":"setting-up.html","audio-and-midi-setup":"setting-up.html","customising":"setting-up.html","recording":"recording.html","takes-and-comping":"recording.html","tracks":"editing-and-arranging.html","editing-audio":"editing-and-arranging.html","arranging":"editing-and-arranging.html","midi-and-instruments":"writing-and-midi.html","drums":"writing-and-midi.html","mixing":"mixing.html","plugins":"mixing.html","finishing-and-exporting":"finishing-and-sharing.html","sharing-with-bandmates":"finishing-and-sharing.html","backups-history-and-recovery":"finishing-and-sharing.html","the-assistant":"help.html","troubleshooting":"help.html","windows-and-mac-differences":"help.html"};

var T5 = (function () {
  function esc(s) { return s.replace(/[&<>"]/g, function (c) { return {"&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;"}[c]; }); }
  function words(q) { return q.trim().toLowerCase().split(/\s+/).filter(Boolean); }

  // The tasks with every word in them, the ones with the words in their title first.
  function find(ws) {
    var hits = [];
    T5_INDEX.forEach(function (e) {
      var title = e[1].toLowerCase(), all = title + " " + e[2].toLowerCase() + " " + e[4];
      if (!ws.every(function (w) { return all.indexOf(w) >= 0; })) return;
      var score = ws.filter(function (w) { return title.indexOf(w) >= 0; }).length;
      hits.push({e: e, score: score});
    });
    hits.sort(function (a, b) { return b.score - a.score; });
    return hits.map(function (h) { return h.e; });
  }

  function snippet(text, ws) {
    var at = -1;
    ws.forEach(function (w) { var i = text.indexOf(w); if (i >= 0 && (at < 0 || i < at)) at = i; });
    var start = Math.max(0, at - 50), s = text.slice(start, start + 150);
    var out = esc((start > 0 ? "…" : "") + s + (start + 150 < text.length ? "…" : ""));
    ws.forEach(function (w) {
      out = out.replace(new RegExp("(" + esc(w).replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + ")", "g"), "<mark>$1</mark>");
    });
    return out;
  }

  // A list of the tasks found, linked, into a box; how many there were.
  function results(q, box, limit) {
    var ws = words(q);
    if (!ws.length) { box.hidden = true; box.innerHTML = ""; return 0; }
    var hits = find(ws);
    var here = location.pathname.split("/").pop() || "index.html";
    box.innerHTML = '<p class="m-res-count">' + (hits.length ? hits.length + (hits.length === 1 ? " task" : " tasks") + " in the manual" : "Nothing in the manual") + "</p>"
      + '<ol>' + hits.slice(0, limit || 40).map(function (e) {
        var href = (e[3] === here ? "" : e[3]) + "#" + e[0];
        return '<li><a href="' + href + '"><b>' + esc(e[1]) + "</b><span>" + esc(e[2]) + "</span><small>" + snippet(e[4], ws) + "</small></a></li>";
      }).join("") + "</ol>";
    box.hidden = false;
    return hits.length;
  }

  function keysToggle() {
    var root = document.documentElement;
    var win = document.getElementById("os-win"), mac = document.getElementById("os-mac");
    if (!win || !mac) return;
    function set(os) {
      root.classList.toggle("mac", os === "mac");
      win.setAttribute("aria-pressed", String(os !== "mac"));
      mac.setAttribute("aria-pressed", String(os === "mac"));
    }
    var saved = null;
    try { saved = localStorage.getItem("take5-keys"); } catch (e) {}
    set(saved || (/Mac/.test(navigator.platform || navigator.userAgent) ? "mac" : "win"));
    function pick(os) { set(os); try { localStorage.setItem("take5-keys", os); } catch (e) {} }
    win.addEventListener("click", function () { pick("win"); });
    mac.addEventListener("click", function () { pick("mac"); });
  }

  // "/" anywhere outside a text box goes to the search.
  function slashTo(input) {
    document.addEventListener("keydown", function (e) {
      if (e.key === "/" && !/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName)) {
        e.preventDefault(); input.focus();
      }
    });
  }

  // Screenshots open over the page, full size (to the window), not in a tab of their own: a click,
  // x or Esc closes it, the arrow keys go through the page's others. (Without scripts the link
  // still opens the image.)
  function lightbox() {
    var shots = [].slice.call(document.querySelectorAll("a.m-shot"));
    if (!shots.length) return;
    var box = document.createElement("div");
    box.className = "lightbox";
    box.hidden = true;
    box.setAttribute("role", "dialog");
    box.setAttribute("aria-modal", "true");
    box.innerHTML = '<button type="button" class="lb-close" aria-label="Close">\u00d7</button>'
      + '<button type="button" class="lb-prev" aria-label="Previous screenshot">\u2039</button>'
      + '<figure><img alt=""><figcaption></figcaption></figure>'
      + '<button type="button" class="lb-next" aria-label="Next screenshot">\u203a</button>';
    document.body.appendChild(box);
    var img = box.querySelector("img"), caption = box.querySelector("figcaption");
    var current = -1, opener = null;

    function show(i) {
      current = (i + shots.length) % shots.length;
      var a = shots[current], thumb = a.querySelector("img");
      img.src = a.getAttribute("href");
      img.alt = thumb ? thumb.alt : "";
      caption.textContent = (thumb ? thumb.alt.replace(/^Screenshot: /, "") : "") + (shots.length > 1 ? "  \u00b7  " + (current + 1) + " of " + shots.length : "");
      box.classList.toggle("single", shots.length < 2);
    }
    function open(i, from) {
      opener = from;
      show(i);
      box.hidden = false;
      document.documentElement.classList.add("lb-open");
      box.querySelector(".lb-close").focus();
    }
    function close() {
      box.hidden = true;
      document.documentElement.classList.remove("lb-open");
      img.removeAttribute("src");
      if (opener) opener.focus();
    }
    shots.forEach(function (a, i) {
      a.addEventListener("click", function (e) {
        if (e.metaKey || e.ctrlKey || e.shiftKey || e.button !== 0) return;   // (a new tab when asked for)
        e.preventDefault();
        open(i, a);
      });
    });
    box.addEventListener("click", function (e) {
      if (e.target.closest(".lb-prev")) show(current - 1);
      else if (e.target.closest(".lb-next")) show(current + 1);
      else close();
    });
    document.addEventListener("keydown", function (e) {
      if (box.hidden) return;
      if (e.key === "Escape") { e.preventDefault(); close(); }
      else if (e.key === "ArrowLeft") { e.preventDefault(); show(current - 1); }
      else if (e.key === "ArrowRight") { e.preventDefault(); show(current + 1); }
    });
  }

  // A part page: the sidebar's search shows its results in place of the contents.
  function manualPage() {
    keysToggle();
    lightbox();
    var input = document.getElementById("m-find"), box = document.getElementById("m-results");
    var toc = document.querySelector(".m-toc");
    var timer = null;
    function run() { var n = results(input.value, box); toc.hidden = !box.hidden; return n; }
    input.addEventListener("input", function () { clearTimeout(timer); timer = setTimeout(run, 120); });
    input.addEventListener("keydown", function (e) {
      if (e.key === "Escape") { input.value = ""; run(); }
      if (e.key === "Enter") { var a = box.querySelector("a"); if (a) a.click(); }
    });
    slashTo(input);
    // The contents follow the reading: the area being read is marked.
    var links = {};
    [].forEach.call(toc.querySelectorAll("a"), function (a) { links[a.getAttribute("href").slice(1)] = a; });
    if ("IntersectionObserver" in window) {
      var current = null;
      var seen = new IntersectionObserver(function (entries) {
        entries.forEach(function (en) {
          if (!en.isIntersecting) return;
          var a = links[en.target.id];
          if (!a) return;
          if (current) current.classList.remove("on");
          current = a; a.classList.add("on");
        });
      }, {rootMargin: "0px 0px -75% 0px"});
      [].forEach.call(document.querySelectorAll(".m-task"), function (t) { seen.observe(t); });
    }
  }

  // The front page: an id it doesn't have (an area or task from the app's links) is on a part page.
  function redirect() {
    var id = decodeURIComponent(location.hash.slice(1));
    if (!id || document.getElementById(id)) return false;
    var page = T5_AREAS[id.split("--")[0]];
    if (page) { location.replace(page + "#" + id); return true; }
    return false;
  }

  return {results: results, manualPage: manualPage, keysToggle: keysToggle, slashTo: slashTo, redirect: redirect};
})();
